/* redesign.css */
:root {
  --vita-text-body:#0C1D7F;
  --vita-text-heading:#0C1D7F;
  --vita-text-secondary:#0C1D7F;
  --vita-font:"General Sans",Arial,sans-serif;
  --vita-gradient:linear-gradient(
      
      125deg,#003BA8 0%,#003BA8 40%,#0C1D7F 75%,#0C1D7F 100%);
  --vita-gradient-deep:linear-gradient(
      
      120deg,#003BA8,#0C1D7F 48%,#0C1D7F);
  --vita-ink:#0C1D7F;
  --vita-muted:#0C1D7F;
  --vita-line:#80D7D918;
  --vita-accent:#80D7D9;
  --vita-blue:#003BA8;
  --vita-deep:#0C1D7F;
  --vita-bg:#80D7D918;
  --vita-aqua:#80D7D966;
  --vs-color-blue-deep:#0C1D7F;
  --vs-color-accent:#80D7D9;
}
*,
:before,
:after {
  box-sizing: border-box;
}
html {
  scroll-behavior: smooth;
  scroll-padding-top: 124px;
}
body {
  margin: 0;
  background:
    radial-gradient(
      ellipse at 30% 2%,
      #80D7D918,
      transparent 35%),
    #80D7D918;
  color: var(--vita-ink);
  font: 400 16px/1.65 var(--vita-font);
}
h1,
h2,
h3,
h4,
p,
figure {
  margin: 0;
}
h1,
h2,
h3,
h4,
button,
input,
select,
textarea,
a {
  font-family: var(--vita-font);
}
a {
  color: inherit;
}
img {
  max-width: 100%;
  height: auto;
  display: block;
}
button,
input,
select,
textarea {
  font: inherit;
}
button {
  cursor: pointer;
}
a,
button {
  -webkit-tap-highlight-color: transparent;
}
button {
  touch-action: manipulation;
}
button:disabled {
  cursor: default;
}
:focus-visible {
  outline: 3px solid #003BA8;
  outline-offset: 4px;
}
::selection {
  background: #80D7D966;
  color: #0C1D7F;
}
.v-icon {
  width: 23px;
  height: 23px;
  display: block;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.65;
  stroke-linecap: round;
  stroke-linejoin: round;
  flex-shrink: 0;
}
.v-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 18px;
  min-height: 48px;
  padding: 12px 21px;
  border: 1px solid transparent;
  border-radius: 13px;
  background: var(--vita-gradient);
  color: #FFFFFF;
  text-decoration: none;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.35;
  transition:
    transform .3s,
    box-shadow .3s,
    background .3s;
}
.v-button .v-icon {
  width: 18px;
  height: 18px;
  transition: transform .3s;
}
.v-button:hover {
  transform: translateY(-3px);
  box-shadow: 0 10px 28px #003BA828;
}
.v-button:hover .v-icon {
  transform: translateX(3px);
}
.v-button--aqua {
  background:
    linear-gradient(
      120deg,
      #80D7D9,
      #80D7D9);
  color: #0C1D7F;
}
.v-button--outline {
  border-color: #80D7D966;
  color: #003BA8;
  background: #FFFFFF;
  background-image: none;
}
.v-button--outline:hover {
  background: #FFFFFF;
  border-color: #80D7D966;
}
.v-button--light {
  background: #FFFFFF10;
  border: 1px solid #FFFFFF40;
  color: white;
  backdrop-filter: blur(20px);
}
.v-button--light:hover {
  background: #FFFFFF25;
}
.v-kicker:before,
.v-kicker:after {
  display: none;
}
.v-skip {
  position: fixed;
  top: 12px;
  left: 12px;
  z-index: 500;
  padding: 12px 20px;
  background: #FFFFFF;
  color: #0C1D7F;
  transform: translateY(-200%);
  border-radius: 10px;
  text-decoration: none;
}
.v-skip:focus {
  transform: translateY(0);
}
.v-header {
  position: sticky;
  top: 12px;
  z-index: 100;
  width: min(1440px, calc(100% - 40px));
  margin: 16px auto 20px;
  border: 1px solid #FFFFFFE6;
  border-radius: 24px;
  background:
    linear-gradient(
      130deg,
      #FFFFFFC9,
      #80D7D9CC);
  backdrop-filter: blur(28px) saturate(1.5);
  -webkit-backdrop-filter: blur(28px) saturate(1.5);
  box-shadow: 0 12px 34px #0C1D7F0D, inset 0 1px #FFFFFF;
  border-bottom-color: #80D7D918;
}
.v-topbar {
  display: none;
}
.v-navrow {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 14px 20px;
  min-height: 78px;
}
.v-brand {
  width: 166px;
  display: block;
  flex-shrink: 0;
}
.v-brand img {
  width: 100%;
  height: auto;
}
.v-nav {
  display: flex;
  gap: 5px;
  align-items: center;
  justify-content: center;
  flex: 1;
  min-width: 0;
}
.v-nav > a,
.v-nav > details > summary {
  display: flex;
  align-items: center;
  min-height: 41px;
  white-space: nowrap;
  font-family: var(--vita-font) !important;
  font-size: 12px;
  font-weight: 600;
  line-height: 1.2;
  text-decoration: none;
  list-style: none;
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 11px 12px;
  background: transparent;
  color: #0C1D7F;
  cursor: pointer;
  transition:
    background .25s,
    color .25s,
    box-shadow .25s,
    transform .25s;
}
.v-nav > details > summary::-webkit-details-marker {
  display: none;
}
.v-nav > a:hover,
.v-nav > details > summary:hover,
.v-nav > a:focus-visible,
.v-nav > details > summary:focus-visible {
  background:
    linear-gradient(
      125deg,
      #80D7D918,
      #80D7D918);
  transform: translateY(-2px);
  box-shadow: 0 5px 12px #003BA812;
}
.v-nav > a:active,
.v-nav > details > summary:active {
  transform: translateY(0) scale(.97);
}
.v-nav > a[aria-current=page],
.v-nav > details[open] > summary {
  color: #003BA8;
}
.v-nav details {
  position: relative;
}
.v-dropdown {
  position: absolute;
  top: calc(100% + 13px);
  left: -8px;
  min-width: 250px;
  padding: 9px;
  border: 1px solid #FFFFFF;
  border-radius: 16px;
  background: #80D7D9F2;
  backdrop-filter: blur(24px);
  box-shadow: 0 18px 45px #0C1D7F1F;
  animation: menuIn .2s ease-out;
}
.v-dropdown a {
  display: block;
  text-decoration: none;
  padding: 11px 14px;
  font-size: 14px;
  line-height: 1.4;
  border-radius: 9px;
  transition: background .2s, color .2s;
}
.v-dropdown a:hover {
  background: #80D7D918;
  color: #003BA8;
}
.v-navrow > .v-button {
  font-size: 12px;
  min-height: 42px;
  padding: 11px 15px;
  white-space: nowrap;
  flex-shrink: 0;
}
.v-mobile-toggle {
  display: none;
}
.s-footer {
  padding: 0;
  background:
    radial-gradient(
      ellipse at 5% 15%,
      #003BA866,
      transparent 55%),
    linear-gradient(
      120deg,
      #003BA8,
      #0C1D7F 44%,
      #0C1D7F);
  color: #FFFFFF;
  position: relative;
  overflow: hidden;
}
.s-footer:after {
  content: "";
  position: absolute;
  inset: auto -15% -400px auto;
  width: 900px;
  height: 900px;
  border: 1px solid #FFFFFF08;
  border-radius: 50%;
  box-shadow: 0 0 0 85px #FFFFFF03, 0 0 0 170px #FFFFFF02;
  pointer-events: none;
}
.s-footer-main {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: .9fr 1.05fr 1.05fr;
  gap: 48px;
  padding: 48px 0 40px;
  align-items: start;
}
.s-footer-brand,
.s-footer-sitemap {
  min-width: 0;
  padding-top: 24px;
}
.s-footer-brand > a:first-child {
  display: block;
  width: 156px;
}
.s-footer-brand img {
  width: 100%;
  filter: brightness(0) invert(1);
}
.s-footer-brand > p {
  color: #80D7D918;
  font-size: 14px;
  line-height: 1.65;
  margin: 22px 0;
  max-width: 280px;
}
.s-footer-brand address {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding-top: 20px;
  border-top: 1px solid #FFFFFF20;
  font-style: normal;
  font-size: 13px;
  color: #80D7D918;
  line-height: 1.7;
}
.s-footer-brand address .v-icon {
  width: 20px;
  height: 20px;
  margin-top: 3px;
}
.s-footer-brand address span {
  display: block;
}
.s-footer-brand address strong {
  font-size: 14px;
  color: white;
  display: block;
  margin-bottom: 4px;
}
.s-linkedin {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  border: 1px solid #FFFFFF3A;
  background: #FFFFFF10;
  text-decoration: none;
  color: white;
  font-size: 17px;
  font-weight: 600;
  margin-top: 24px;
  transition: background .25s, transform .25s;
}
.s-linkedin:hover {
  background: #FFFFFF30;
  transform: translateY(-3px);
}
.s-footer h2 {
  color: #FFFFFF;
  font-size: 21px;
  line-height: 1.25;
  font-weight: 700;
  letter-spacing: -.025em;
  margin: 0 0 24px;
}
.s-footer h2:after {
  content: "";
  display: block;
  width: 30px;
  height: 3px;
  border-radius: 3px;
  background:
    linear-gradient(
      90deg,
      #80D7D9,
      #80D7D9);
  margin-top: 12px;
}
.s-footer-sitemap ul {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px 20px;
  list-style: none;
  margin: 0;
  padding: 0;
}
.s-footer-sitemap li {
  margin: 0;
}
.s-footer-sitemap a {
  font-size: 14px;
  font-weight: 400;
  line-height: 1.5;
  color: #80D7D918;
  text-decoration: none;
  display: flex;
  align-items: center;
  min-height: 34px;
  padding: 5px 0;
  transition: color .25s, transform .25s;
}
.s-footer-sitemap a:hover {
  color: #80D7D9;
  transform: translateX(4px);
}
.s-footer-attend {
  min-width: 0;
  border: 1px solid #FFFFFF29;
  border-radius: 22px;
  background:
    linear-gradient(
      140deg,
      #FFFFFF12,
      #FFFFFF07);
  box-shadow: inset 0 1px #FFFFFF16;
  backdrop-filter: blur(20px);
  padding: 24px;
}
.s-footer-client {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  background:
    linear-gradient(
      120deg,
      #80D7D9,
      #80D7D9);
  color: #0C1D7F;
  padding: 17px 19px;
  border-radius: 13px;
  text-decoration: none;
  font-size: 16px;
  line-height: 1.3;
  font-weight: 700;
  margin-bottom: 12px;
  transition: transform .25s, box-shadow .25s;
}
.s-footer-client small {
