}
.s-footer-icon {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  background: #FFFFFF10;
  color: #80D7D918;
  border-radius: 11px;
  flex-shrink: 0;
}
.s-footer-icon .v-icon {
  width: 18px;
  height: 18px;
}
.s-footer-contact:hover,
.s-footer-contact:focus-visible {
  background: #FFFFFF0B;
  border-color: #FFFFFF22;
}
.s-footer-contact:hover strong,
.s-footer-contact:focus-visible strong {
  color: #80D7D9;
}
.s-footer-bottom {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 20px 0 24px;
  border-top: 1px solid #FFFFFF20;
  font-size: 11px;
  line-height: 1.6;
  color: #80D7D966;
}
.s-footer-bottom > div {
  display: flex;
  gap: 22px;
}
.s-footer-bottom a {
  text-decoration: none;
  color: inherit;
  display: inline-flex;
  align-items: center;
  min-height: 32px;
}
.s-footer-bottom a:hover {
  color: #FFFFFF;
}
.v-news-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 26px;
}
.v-news {
  display: block;
  background: #FFFFFF;
  border: 1px solid #80D7D918;
  border-radius: 21px;
  overflow: hidden;
  text-decoration: none;
  transition: transform .35s, box-shadow .35s;
}
.v-news > img,
.v-news-brand {
  height: 270px;
  width: 100%;
  object-fit: cover;
}
.v-news > img {
  transition: transform .65s;
}
.v-news:hover {
  transform: translateY(-7px);
  box-shadow: 0 25px 50px #0C1D7F10;
}
.v-news:hover > img {
  transform: scale(1.035);
}
.v-news-brand {
  display: grid;
  place-items: center;
  background:
    radial-gradient(
      ellipse at 30% 25%,
      #80D7D918,
      transparent 65%),
    linear-gradient(
      130deg,
      #80D7D918,
      #80D7D918);
}
.v-news-brand img {
  width: 180px;
  height: auto;
}
.v-news-copy {
  padding: 28px;
}
.v-news-copy time {
  font-size: 12px;
  color: #0C1D7F;
}
.v-news-copy h3 {
  font-size: 25px;
  font-weight: 700;
  line-height: 1.3;
  letter-spacing: -.025em;
  color: #0C1D7F;
  margin: 15px 0 20px;
}
.v-news-copy > span {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 13px;
  color: #0C1D7F;
}
.v-news-copy > span .v-icon {
  width: 18px;
  height: 18px;
}
.v-extra-body {
  padding: 65px 0;
}
.v-extra-grid {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 50px;
}
.v-info-card {
  background:
    linear-gradient(
      130deg,
      #80D7D918,
      #FFFFFF);
  border: 1px solid #80D7D918;
  border-radius: 22px;
  padding: 30px;
}
.v-info-card hr {
  border: 0;
  border-top: 1px solid #80D7D966;
  margin: 24px 0;
}
.v-extra-body h2 {
  font-size: 35px;
  letter-spacing: -.03em;
  line-height: 1.2;
  font-weight: 700;
  margin-bottom: 25px;
}
.v-extra-body p {
  margin-bottom: 22px;
}
.v-info-card h2 {
  font-size: 24px;
}
.v-info-card p,
.v-info-card a {
  font-size: 15px;
}
@keyframes menuIn {
  from {
    opacity: 0;
    transform: translateY(-7px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
[data-reveal] {
  transition: opacity .75s ease, transform .75s cubic-bezier(.18, .75, .25, 1);
}
html.reveal-enabled [data-reveal]:not(.is-visible) {
  opacity: 0;
  transform: translateY(28px);
}
html.reveal-enabled [data-reveal].is-visible {
  opacity: 1;
  transform: none;
}
@media (max-width: 1250px) {
  .v-navrow {
    gap: 12px;
    padding-inline: 16px;
  }
  .v-brand {
    width: 151px;
  }
  .v-nav > a,
  .v-nav > details > summary {
    font-size: 11px;
    padding-inline: 9px;
  }
  .v-navrow > .v-button {
    font-size: 11px;
    padding-inline: 12px;
  }
  .s-footer-main {
    gap: 40px;
  }
}
@media (max-width: 1080px) {
  .v-nav {
    display: none;
  }
  .v-mobile-toggle {
    display: grid;
    place-items: center;
    margin-left: auto;
    border: 1px solid #80D7D918;
    background: #FFFFFF7D;
    border-radius: 12px;
    color: #0C1D7F;
    width: 42px;
    height: 42px;
    flex-shrink: 0;
  }
  .v-mobile-toggle:hover,
  .v-mobile-toggle[aria-expanded=true] {
    background: #80D7D918;
  }
  .v-nav.is-open {
    display: flex;
    position: absolute;
    top: calc(100% + 10px);
    left: 0;
    right: 0;
    flex-direction: column;
    align-items: stretch;
    gap: 7px;
    border-radius: 22px;
    padding: 16px;
    background: #80D7D9F5;
    backdrop-filter: blur(28px);
    -webkit-backdrop-filter: blur(28px);
    border: 1px solid #FFFFFF;
    box-shadow: 0 22px 45px #0C1D7F20;
    max-height: calc(100dvh - 135px);
    overflow: auto;
    animation: menuIn .25s;
  }
  .v-nav.is-open > a,
  .v-nav.is-open > details > summary {
    font-size: 14px;
    padding: 12px 14px;
    background: #80D7D970;
    min-height: 44px;
  }
  .v-nav.is-open .v-dropdown {
    position: static;
    box-shadow: none;
    min-width: 0;
    border: 0;
    background: transparent;
    padding: 7px 7px 0;
  }
  .v-nav.is-open > details[open] > summary {
    background: var(--vita-gradient);
  }
  .s-footer-main {
    grid-template-columns: 1fr 1fr;
  }
  .s-footer-attend {
    grid-column: 1/-1;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0 20px;
  }
  .s-footer-attend h2 {
    grid-column: 1/-1;
  }
  .s-footer-client {
    margin: 0 0 12px;
    grid-column: 1/-1;
    grid-row: auto;
    align-self: start;
  }
  .s-footer-contact {
    border-top-color: #FFFFFF16;
    padding: 12px 8px;
    min-height: 96px;
  }
  .s-footer-brand > a:first-child {
    width: 155px;
  }
}
@media (max-width: 760px) {
  html {
    scroll-padding-top: 110px;
  }
  .v-header {
    top: 8px;
    width: calc(100% - 24px);
    margin: 12px auto 16px;
    border-radius: 20px;
  }
  .v-navrow {
    padding: 12px 13px;
    min-height: 67px;
    gap: 10px;
  }
  .v-brand {
    width: 135px;
  }
  .v-mobile-toggle {
    width: 44px;
    height: 44px;
    border-radius: 10px;
  }
  .v-navrow > .v-button {
    min-height: 39px;
    padding: 9px 11px;
    font-size: 11px;
    border-radius: 10px;
  }
  .v-button {
    font-size: 13px;
    padding: 12px 17px;
    min-height: 46px;
    gap: 13px;
  }
  .v-news-grid {
    grid-template-columns: 1fr;
    gap: 20px;
  }
  .v-news > img,
  .v-news-brand {
    height: 210px;
  }
  .v-news-copy {
    padding: 24px;
  }
  .v-news-copy h3 {
    font-size: 23px;
  }
  .s-footer-main {
    display: grid;
    grid-template-columns: 1fr;
    gap: 32px;
    padding: 36px 0 30px;
  }
  .s-footer-brand,
  .s-footer-sitemap {
    padding-top: 0;
  }
  .s-footer-brand {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 18px 20px;
    align-items: center;
  }
  .s-footer-brand > a:first-child {
    width: 120px;
  }
  .s-footer .s-linkedin {
    width: 44px;
    height: 44px;
  }
  .s-footer-brand > p {
    margin: 0;
    font-size: 12px;
  }
  .s-footer-brand address {
    grid-column: 1/-1;
    padding-top: 19px;
    font-size: 12px;
  }
  .s-linkedin {
    margin: 0;
    grid-column: 1;
    grid-row: 3;
    justify-self: start;
    width: 44px;
    height: 44px;
    font-size: 15px;
  }
  .s-footer h2 {
    font-size: 20px;
    margin-bottom: 22px;
  }
  .s-footer-sitemap ul {
    gap: 4px 20px;
  }
  .s-footer-sitemap a {
    font-size: 13px;
    min-height: 44px;
    padding: 10px 0;
  }
  .s-footer-attend {
    grid-column: auto;
    display: block;
    padding: 22px;
    border-radius: 20px;
  }
  .s-footer-client {
    margin-bottom: 14px;
    font-size: 16px;
    padding: 16px;
  }
  .s-footer-contact {
    min-height: 76px;
    padding: 14px 8px;
    border-top-color: #FFFFFF19;
  }
  .s-footer-contact strong {
    font-size: 12px;
  }
  .s-footer-bottom {
    display: block;
    font-size: 10px;
    padding: 20px 0 26px;
  }
  .s-footer-bottom > div {
    margin-top: 10px;
    gap: 4px 16px;
    flex-wrap: wrap;
  }
  .s-footer-bottom a {
    min-height: 44px;
  }
  .v-extra-grid {
    grid-template-columns: 1fr;
    gap: 26px;
  }
  .v-extra-body {
    padding: 43px 0;
  }
  .v-extra-body h2 {
    font-size: 29px;
  }
  .v-info-card {
    padding: 24px;
  }
  .v-info-card h2 {
    font-size: 23px;
  }
}
@media (max-width: 370px) {
  .v-brand {
    width: 110px;
  }
  .v-navrow {
    gap: 7px;
    padding-inline: 11px;
  }
  .v-navrow > .v-button {
    width: 82px;
    white-space: normal;
    text-align: center;
    font-size: 11px;
    line-height: 1.25;
    padding: 8px;
  }
  .v-mobile-toggle {
    width: 40px;
  }
  .s-footer-brand {
    grid-template-columns: 100px 1fr;
    gap: 18px;
  }
  .s-footer-brand > a:first-child {
    width: 100px;
  }
}
@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  *,
  *:before,
  *:after {
    animation: none !important;
    transition: none !important;
  }
  html.reveal-enabled [data-reveal] {
    opacity: 1 !important;
    transform: none !important;
  }
}

