/* home.css */
/* Hero: supplied artwork on desktop, readable composition on smaller screens. */
.s-hero {
  width: 100%;
  margin: 0;
  padding: 0;
  color: #FFFFFF;
  background: #0C1D7F;
  isolation: isolate;
}
.s-hero-track {
  display: grid;
  position: relative;
  min-width: 0;
  overflow: hidden;
}
.s-slide {
  display: none;
  grid-area: 1 / 1;
  min-width: 0;
}
.s-slide.is-active {
  display: block;
  animation: campaign-appear .35s ease both;
}
@keyframes campaign-appear {
  from { opacity: 0; }
  to { opacity: 1; }
}
.campaign-desktop {
  display: block;
  line-height: 0;
  width: 100%;
}
.campaign-desktop > img {
  display: block;
  width: 100%;
  max-width: 100%;
  height: auto;
}
.campaign-desktop:focus-visible {
  outline: 3px solid #80D7D9;
  outline-offset: -3px;
}
.campaign-mobile {
  display: none;
}
.s-carousel-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  width: 100%;
  margin: 0;
  padding: 8px max(16px, calc((100% - 1240px) / 2));
  background: #0C1D7F;
}
.s-carousel-count {
  display: flex;
  gap: 6px;
  flex: 0 0 auto;
  font-size: 14px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: #FFFFFF;
}
.s-carousel-total { color: #80D7D918; }
.s-carousel-dots, .s-carousel-actions {
  display: flex;
  align-items: center;
  gap: 4px;
}
.s-carousel-bar button {
  display: grid;
  place-items: center;
  cursor: pointer;
  border: 0;
  min-width: 44px;
  min-height: 44px;
  padding: 0;
  color: #FFFFFF;
  background: transparent;
  border-radius: 10px;
  transition: background .2s, color .2s;
}
.s-carousel-dots button span {
  display: block;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #80D7D966;
  transition: width .2s, background .2s;
}
.s-carousel-dots button[aria-pressed="true"] span {
  width: 28px;
  border-radius: 8px;
  background: #80D7D9;
}
.s-carousel-bar button:hover {
  color: #0C1D7F;
  background: #80D7D9;
}
.s-carousel-bar button:focus-visible {
  outline: 2px solid #80D7D9;
  outline-offset: -2px;
}
.s-carousel-actions svg { width: 20px; height: 20px; }
@media (max-width: 960px) {
  .campaign-desktop { display: none; }
