    color: inherit;
    font-size: 17px;
    line-height: 1.55;
    font-weight: 600;
  }
  .v-home .campaign-copy .campaign-closing {
    margin: 0 0 20px;
    color: inherit;
    font-size: 16px;
    line-height: 1.5;
    font-weight: 600;
  }
  .campaign-copy .v-button {
    max-width: 100%;
    min-height: 48px;
    white-space: normal;
    justify-content: space-between;
  }
  .campaign-portrait {
