    gap: 12px;
    min-height: 48px;
    padding: 10px 14px;
    border: 1px solid #80D7D918;
    border-radius: 12px;
    color: #0C1D7F;
    background: #FFFFFF;
    font-size: 16px;
    line-height: 1.4;
    font-weight: 700;
    text-decoration: none;
  }
  .campaign-contact-links svg {
    width: 20px;
    height: 20px;
    flex: 0 0 20px;
  }
  .campaign-contact-links a:hover { background: #80D7D9; }
  .campaign-contact-links a:focus-visible {
    outline: 2px solid #0C1D7F;
    outline-offset: 2px;
  }
}
@media (max-width: 600px) {
  .campaign-mobile {
    grid-template-columns: minmax(0, 1fr);
    gap: 24px;
    padding-block: 24px;
  }
  .v-home .campaign-copy .campaign-title {
    font-size: 32px;
  }
  .campaign-portrait {
    width: min(100%, 420px);
    margin-inline: auto;
    border-radius: 16px;
  }
  .s-carousel-bar {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 4px 8px;
  }
  .s-carousel-count { grid-column: 1; grid-row: 1; }
  .s-carousel-actions { grid-column: 2; grid-row: 1; }
  .s-carousel-dots {
    grid-column: 1 / -1;
    grid-row: 2;
    justify-content: center;
  }
  .s-carousel-count { gap: 4px; font-size: 13px; }
