}
@media (max-width: 360px) {
  .v-home .campaign-copy .campaign-title { font-size: 28px; }
}
@media (prefers-reduced-motion: reduce) {
  .s-slide.is-active { animation: none; }
  .s-carousel-bar button, .s-carousel-dots button span { transition: none; }
}

