    radial-gradient(
      ellipse at 30% 35%,
      #80D7D988,
      transparent 45%),
    #80D7D918;
}
.s-video-copy {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px;
  background:
    linear-gradient(
      90deg,
      #0C1D7F77,
      #0C1D7F22);
}
.s-video-copy p {
  max-width: 850px;
  text-align: center;
  font-size: clamp(32px, 4vw, 61px);
  line-height: 1.15;
  font-weight: 600;
  letter-spacing: -.035em;
  color: white;
  text-shadow: 0 2px 20px #0C1D7F66;
}
.s-agency {
  margin: 26px 0 0;
}
.s-section {
  padding: 85px 0;
}
.s-section h2 {
  font-size: clamp(32px, 3.25vw, 47px);
  line-height: 1.16;
  letter-spacing: -.041em;
  font-weight: 700;
  color: #0C1D7F;
}
.s-section h2 em {
  font-style: normal;
  color: #0C1D7F;
}
.s-split-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 65px;
  margin-bottom: 44px;
}
.s-split-heading > div:first-child {
  flex: 1;
}
.s-heading-copy {
  max-width: 430px;
  flex: 0 1 430px;
}
.s-heading-copy p {
  color: #0C1D7F;
  font-size: 16px;
  line-height: 1.7;
  margin-bottom: 17px;
  font-weight: 600;
}
.s-text-link {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  font-size: 12px;
  font-weight: 500;
  text-decoration: none;
  color: #0C1D7F;
  transition: color .25s;
}
.s-text-link > .v-icon {
  width: 16px;
  height: 16px;
  transition: transform .3s;
}
.s-text-link:hover {
  color: #003BA8;
}
.s-text-link:hover .v-icon {
  transform: translateX(4px);
}
.s-icon-tile {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  background:
    linear-gradient(
      135deg,
      #80D7D918,
      #80D7D918);
  color: #0C1D7F;
  border: 1px solid #80D7D966;
  border-radius: 8px;
  flex-shrink: 0;
  box-shadow: 0 4px 5px #003BA820;
}
.s-icon-tile .v-icon {
  width: 19px;
  height: 19px;
  stroke-width: 1.5;
}
.s-centered-heading {
  text-align: center;
  max-width: 950px;
  margin: 0 auto 47px;
}
.s-centered-heading .s-tag {
  margin-inline: auto;
}
.s-quality-art {
  top: 1px;
  left: 35px;
  right: -38px;
  height: 237px;
}
.s-cycle-art {
  left: 7px;
  right: -38px;
  height: 235px;
  top: -12px;
}
.cycle-badge--water {
  animation: heroFloat 7s ease-in-out infinite;
}
.cycle-badge--leaf {
  animation: heroFloat 9s ease-in-out infinite;
}
.cycle-badge--cactus {
  animation: heroFloat 8s ease-in-out infinite;
}
.s-network-art {
  position: relative;
  align-self: stretch;
}
.s-network-art > svg {
  position: absolute;
  width: 150%;
  height: 100%;
  right: -12%;
  bottom: -10px;
  opacity: .7;
}
.network-flow {
  animation: pipeFlow 14s linear infinite;
}
.s-floating-service {
  display: flex;
  align-items: center;
  gap: 12px;
  background: #80D7D9E0;
  border: 1px solid #FFFFFFF0;
  border-radius: 15px;
  padding: 19px 24px;
  box-shadow: 0 12px 28px #003BA815;
  backdrop-filter: blur(20px);
  position: absolute;
  font-size: 12px;
  line-height: 1.55;
  color: #0C1D7F;
  min-width: 220px;
  transform: rotate(-3deg);
  transition: transform .6s;
}
.s-floating-service strong {
  font-weight: 500;
  color: #0C1D7F;
}
.s-floating-service .v-icon {
  width: 29px;
  height: 29px;
  color: #0C1D7F;
  stroke-width: 1.3;
}
.s-floating-service--water {
  top: 10px;
  left: 15px;
  animation: glassFloat 8s ease-in-out infinite;
}
.s-floating-service--sewage {
  right: 0;
  bottom: 22px;
  transform: rotate(3deg);
  animation: glassFloat 9s ease-in-out infinite reverse;
}
.s-round-link {
  position: absolute;
  z-index: 1;
  right: 27px;
  bottom: 31px;
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: #FFFFFF20;
  border: 1px solid #FFFFFF50;
  backdrop-filter: blur(18px);
  transition: background .3s, transform .3s;
}
.s-round-link .v-icon {
  width: 19px;
  height: 19px;
}
.s-phone-art {
  top: -3px;
  left: 57px;
  right: -52px;
  height: 225px;
}
.s-milestone-grid {
  display: grid;
  grid-template-columns: 1.1fr 1fr 1fr;
  gap: 40px;
  align-items: center;
}
.s-milestone-grid h2 {
  font-size: 34px;
}
.s-milestone-grid article {
  border-left: 1px solid #80D7D966;
  padding-left: 28px;
}
.s-milestone-grid article > span {
  font-size: 12px;
  color: #0C1D7F;
}
.s-milestone-grid h3 {
  font-size: 21px;
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: -.025em;
  margin: 14px 0;
}
.s-milestone-grid article > p {
  font-size: 14px;
  color: #0C1D7F;
  line-height: 1.6;
}
@keyframes heroFloat {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-9px);
  }
}
@keyframes dropFall {
  0%, 15% {
    opacity: 0;
    transform: translateY(-7px);
  }
  30%, 70% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: translateY(28px);
  }
}
@keyframes pipeFlow {
  to {
    stroke-dashoffset: -300;
  }
}
@keyframes glassFloat {
  0%, 100% {
    translate: 0 0;
  }
  50% {
    translate: 0-7px;
  }
}
@media (max-width: 1150px) {
  .s-floating-service {
    min-width: 195px;
    padding: 16px 19px;
  }
  .s-floating-service--water {
    left: 0;
  }
  .s-floating-service--sewage {
    right: -5px;
  }
}
@media (max-width: 760px) {
  .s-video-copy {
    padding: 20px;
  }
  .s-video-copy p {
    font-size: clamp(16px, 4.3vw, 23px);
    line-height: 1.2;
    max-width: 300px;
  }
  .s-video-copy p {
    font-size: 34px;
  }
  .s-agency {
    margin-top: 20px;
  }
  .s-section {
    padding: 54px 0;
  }
  .s-section h2 {
    font-size: 32px;
    line-height: 1.16;
    letter-spacing: -.035em;
  }
  .s-split-heading {
    display: block;
    margin-bottom: 28px;
  }
  .s-heading-copy {
    margin-top: 22px;
    max-width: 100%;
  }
  .s-heading-copy p {
    font-size: 14px;
    line-height: 1.7;
    margin-bottom: 14px;
    font-weight: 600;
  }
  .s-split-heading > .v-button {
    margin-top: 22px;
  }
  .s-icon-tile {
    width: 29px;
    height: 29px;
  }
  .s-icon-tile .v-icon {
    width: 17px;
    height: 17px;
  }
  .s-centered-heading {
    margin-bottom: 30px;
  }
  .s-centered-heading h2 {
    font-size: 30px;
  }
  .s-centered-heading h2 br {
    display: none;
  }
  .s-quality-art {
    left: 41%;
    right: -45px;
    top: 39px;
    height: 226px;
  }
  .s-cycle-art {
    left: -6px;
    right: -33px;
    height: 155px;
    top: -3px;
  }
  .s-network-art {
    height: 175px;
    width: 100%;
    flex-shrink: 0;
    margin-top: 21px;
  }
  .s-network-art > svg {
    width: 140%;
    right: -20%;
    bottom: -20px;
  }
  .s-floating-service {
    font-size: 10px;
    padding: 14px 18px;
    min-width: 180px;
    border-radius: 12px;
    gap: 11px;
  }
  .s-floating-service--water {
    top: 0;
    left: -1px;
  }
  .s-floating-service--sewage {
    bottom: 12px;
    right: -7px;
  }
  .s-floating-service .v-icon {
    width: 24px;
    height: 24px;
  }
  .s-round-link {
    right: 22px;
    bottom: 24px;
    width: 37px;
    height: 37px;
  }
  .s-phone-art {
    left: 38%;
    right: -35px;
    top: 26px;
    height: 250px;
  }
  .s-milestone-grid {
    grid-template-columns: 1fr;
    gap: 26px;
  }
  .s-milestone-grid h2 {
    font-size: 30px;
  }
  .s-milestone-grid article {
    padding-left: 21px;
  }
  .s-milestone-grid article > span {
    font-size: 11px;
  }
  .s-milestone-grid h3 {
    font-size: 20px;
    margin: 11px 0;
  }
  .s-milestone-grid article > p {
    font-size: 13px;
  }
}
@media (max-width: 370px) {
  .s-quality-art {
    left: 38%;
    right: -40px;
    top: 44px;
    height: 210px;
  }
  .s-phone-art {
    left: 39%;
    right: -53px;
    top: 35px;
    height: 235px;
  }
  .s-cycle-art {
    left: 40%;
    right: -20px;
    top: 10px;
    height: 190px;
  }
  .s-centered-heading h2 {
    font-size: 28px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .s-network-art * {
    animation: none !important;
  }
}
@media (min-width: 761px) and (max-width: 1150px) {
}

/* brand.css */
:root {
  --brand-navy:#0C1D7F;
  --brand-accent:#80D7D9;
  --brand-gradient:linear-gradient(
      
      125deg,#003BA8,#003BA8 58%,#0C1D7F);
}
body {
  font-family: var(--vita-font);
  background: #FFFFFF;
}
button,
input,
select,
textarea,
summary {
  font-family: inherit;
}
h1,
h2,
h3,
h4 {
  font-family: var(--vita-font) !important;
  font-weight: 700 !important;
  overflow-wrap: break-word;
}
p {
  overflow-wrap: break-word;
}
a,
button,
summary {
  touch-action: manipulation;
}
a:focus-visible,
button:focus-visible,
summary:focus-visible,
select:focus-visible {
  outline: 3px solid #80D7D9;
  outline-offset: 4px;
}
html {
  scroll-padding-top: 120px;
}
section[id],
details[id] {
  scroll-margin-top: 120px;
}
.brand-utility {
  background: var(--brand-gradient);
  color: white;
  position: relative;
  z-index: 50;
}
.brand-utility-inner {
  max-width: 1320px;
  margin: auto;
  padding: 9px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  font-size: 14px;
  font-weight: 600;
}
.brand-utility nav {
  display: flex;
  gap: 20px;
  align-items: center;
}
.brand-utility a {
  color: #FFFFFF;
  text-decoration: none;
  min-height: 36px;
  display: flex;
  align-items: center;
  gap: 7px;
  border-radius: 8px;
  padding: 6px 9px;
  transition: background .2s, color .2s;
}
.brand-utility a:hover,
.brand-utility a:focus-visible {
  background: var(--brand-accent);
  color: var(--brand-navy);
}
.brand-utility .brand-service {
  background: var(--brand-accent);
  color: var(--brand-navy);
  padding: 9px 16px;
}
.v-header.brand-header {
  position: sticky;
  top: 12px;
  z-index: 45;
  width: min(1320px, calc(100% - 48px));
  margin: 14px auto;
  border-radius: 26px;
  border: 1px solid #FFFFFF;
  background:
    linear-gradient(
      125deg,
      #FFFFFFED,
      #80D7D9D9);
  backdrop-filter: blur(24px) saturate(1.5);
  box-shadow: 0 8px 26px #0C1D7F12;
  overflow: visible;
  padding: 0;
}
.brand-navrow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 15px 22px;
  min-height: 84px;
}
.brand-header .v-brand {
  flex: 0 0 143px;
}
.brand-header .v-brand img {
  width: 143px;
  height: 61px;
  object-fit: contain;
}
.brand-header .brand-nav {
  position: static;
  display: flex;
  align-items: center;
  gap: 3px;
  background: none;
  border: 0;
  padding: 0;
  box-shadow: none;
  flex: 1;
  justify-content: flex-end;
}
.brand-nav > details {
  position: static;
}
.brand-nav > details > summary,
.brand-nav > .brand-nav-contact {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 13px 8px;
  min-height: 48px;
  font: 600 14px/1.25 var(--vita-font) !important;
  color: var(--brand-navy);
  background: transparent;
  border: 0;
  border-radius: 11px;
  text-decoration: none;
  transition: background .2s, transform .2s;
}
.brand-nav summary::after {
  content: "\2304";
  font-size: 14px;
  margin-left: 3px;
}
.brand-nav summary::marker,
.brand-nav summary::-webkit-details-marker {
  display: none;
  content: "";
}
.brand-nav > details:hover > summary,
.brand-nav > details[open] > summary,
.brand-nav > .brand-nav-contact:hover {
  background:
    linear-gradient(
      120deg,
      #80D7D9,
      #80D7D9);
  color: #0C1D7F;
}
.brand-nav summary:active,
.brand-nav > a:active {
  transform: scale(.97);
}
.brand-mega {
  position: absolute;
  top: calc(100% - 3px);
  left: 0;
  right: 0;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  padding: 30px 34px;
  background:
    linear-gradient(
      135deg,
      #FFFFFFFA,
      #80D7D9FA);
  border: 1px solid #80D7D918;
  border-top: 3px solid var(--brand-accent);
  box-shadow: 0 25px 35px #0C1D7F19;
  border-radius: 0 0 24px 24px;
  backdrop-filter: blur(25px);
}
.brand-mega::before {
  content: "";
  position: absolute;
  bottom: 100%;
  height: 16px;
  left: 0;
  right: 0;
}
.brand-mega-column {
  padding: 0 24px;
  border-right: 1px solid #80D7D966;
}
.brand-mega-column:first-child {
  padding-left: 0;
}
.brand-mega-column:last-child {
  border: 0;
}
.brand-mega-column h2 {
  font-size: 20px;
  margin: 0 0 15px;
  color: #003BA8;
}
.brand-mega-column a {
  display: block;
  font-size: 16px;
  line-height: 1.4;
  color: #0C1D7F;
  padding: 12px 10px;
  margin: 1px -10px;
  border-radius: 9px;
  text-decoration: none;
  min-height: 44px;
}
.brand-mega-column a:hover {
  background: #80D7D9;
  color: #0C1D7F;
}
.brand-header .v-mobile-toggle {
  display: none;
}
.brand-icon {
  width: 94px;
  height: 94px;
  object-fit: contain;
  flex-shrink: 0;
}
.brand-card-icon {
  width: 88px;
  height: 88px;
  object-fit: contain;
  display: block;
  margin: 0 0 14px;
}
.vs-quick__icon .brand-icon {
  width: 65px;
  height: 65px;
  max-width: none;
}
.vs-quick__icon {
  width: 66px !important;
  height: 66px !important;
}
.vs-quick__label {
  font-size: 16px !important;
  line-height: 1.35 !important;
}
.vs-quick__item:hover {
  background: #80D7D9 !important;
  border-color: #80D7D9 !important;
}
.v-button,
.vs-inst-btn,
.vs-inst-button {
  font-size: 16px !important;
  font-weight: 600 !important;
  min-height: 48px;
}
.v-button:hover,
.vs-inst-btn:hover,
.vs-inst-button:hover {
  background:
    linear-gradient(
      120deg,
      #80D7D9,
      #80D7D9) !important;
  color: #0C1D7F !important;
  border-color: #80D7D9 !important;
  transform: translateY(-2px);
}
.v-home h2,
.brand-territory h2 {
  font-size: clamp(34px, 3.5vw, 49px);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -.035em;
  margin: 0;
}
.v-home h2 em,
.brand-territory h2 em {
  font-style: normal;
  color: #003BA8;
}
.s-text-link {
  font-size: 17px;
  display: inline-flex;
  gap: 12px;
  align-items: center;
  font-weight: 600;
  color: #0C1D7F;
  text-decoration: none;
  min-height: 48px;
}
.s-text-link:hover {
  color: #80D7D9;
}
.s-text-link .v-icon {
  width: 20px;
  height: 20px;
}
.v-home {
  background: #FFFFFF;
}
.brand-agency {
  padding: 45px 0;
  background: #FFFFFF;
}
.brand-agency-inner {
  display: grid;
  grid-template-columns: .7fr 2fr;
  gap: 45px;
  align-items: center;
}
.brand-agency-heading h2 {
  font-size: 37px;
  color: #0C1D7F;
}
.brand-agency-heading .s-text-link {
  margin-top: 16px;
}
.brand-services {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}
.brand-services > a {
  border: 1px solid #80D7D966;
  background:
    linear-gradient(
      135deg,
      #80D7D918,
      #FFFFFF);
  border-radius: 18px;
  display: grid;
  grid-template-columns: 1fr 24px;
  grid-template-rows: 78px auto;
  align-items: center;
  gap: 9px;
  padding: 18px;
  color: #0C1D7F;
  text-decoration: none;
  transition: background .25s, transform .25s;
  min-height: 151px;
}
.brand-services .brand-icon {
  grid-column: 1/-1;
  width: 82px;
  height: 82px;
  justify-self: start;
}
.brand-services span {
  font-size: 17px;
  line-height: 1.3;
  font-weight: 600;
}
.brand-services .v-icon {
  width: 22px;
  height: 22px;
  justify-self: end;
}
.brand-services > a:hover {
  background:
    linear-gradient(
      135deg,
      #80D7D9,
      #80D7D9);
  border-color: #80D7D9;
  transform: translateY(-4px);
}
.brand-services > a:hover img {
  transform: rotate(-4deg) scale(1.06);
}
.brand-services img {
  transition: transform .3s;
}
.brand-about {
  position: relative;
  padding: 55px 0;
  background: var(--brand-gradient);
  isolation: isolate;
}
.brand-about::before {
  position: absolute;
  content: "";
  inset: 0;
  background: url("data:image/webp;base64,")right/cover;
  opacity: .3;
  z-index: -1;
}
.brand-about-grid {
  display: grid;
  grid-template-columns: .95fr 1.05fr;
  align-items: center;
  gap: 48px;
}
.brand-about-copy h2 {
  color: #FFFFFF;
  font-size: 43px;
}
.brand-about-copy h2 em {
  color: #80D7D9;
}
.brand-about-copy > p:not(.s-tag) {
  color: #80D7D918;
  font-size: 19px;
  line-height: 1.65;
  margin: 22px 0;
}
.brand-territory {
  background: #80D7D918;
  padding: 55px 0;
  color: #0C1D7F;
}
.brand-section-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 40px;
  margin-bottom: 30px;
}
.brand-section-heading > p {
  max-width: 400px;
  font-size: 18px;
  line-height: 1.65;
  color: #0C1D7F;
  margin: 0;
  font-weight: 500;
}
.brand-map-layout {
  display: grid;
  grid-template-columns: 1.55fr 1fr;
  border-radius: 24px;
  overflow: hidden;
  border: 1px solid #80D7D918;
  background: white;
  box-shadow: 0 15px 35px #0C1D7F10;
}
.brand-map-viewport {
  position: relative;
  overflow: auto;
  max-height: 525px;
  min-height: 400px;
  background:
    linear-gradient(
      130deg,
      #80D7D918,
      #FFFFFF);
  overscroll-behavior: contain;
}
.brand-map-canvas {
  position: relative;
  width: 100%;
  min-width: 600px;
  aspect-ratio: 1787/1395;
  transition: width .25s;
  margin: auto;
}
.brand-map-base {
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
  padding: 12px;
}
.brand-map-pin {
  position: absolute;
  transform: translate(-50%, -50%);
  width: 35px;
  height: 35px;
