/* hero-map.css */
.ma {
  --ma-scheme: escuro;
  --ma-bg:#0C1D7F;
  --ma-bg-glass:rgba(12,29,127,.82);
  --ma-surface:#0C1D7F;
  --ma-raise:#0C1D7F;
  --ma-line:color-mix(in srgb,color-mix(in srgb,#80D7D9 23%,#FFFFFF) 10%,transparent);
  --ma-line-2:color-mix(in srgb,color-mix(in srgb,#80D7D9 23%,#FFFFFF) 18%,transparent);
  --ma-ink:#80D7D918;
  --ma-mute:#80D7D9;
  --ma-faint:#60CCCF;
  --ma-brand:#80D7D9;
  --ma-navy:#0C1D7F;
  --ma-fill-lo:#0C1D7F;
  --ma-fill-hi:#80D7D9;
  --ma-fill-hot:#80D7D918;
  --ma-bullet:#80D7D9;
  --ma-ctx:#0C1D7F;
  --ma-mesh:#0C1D7F;
  --ma-state:#0C1D7F;
  --ma-water:#0C1D7F;
  --ma-river:#0C1D7F;
  --ma-water-ink:rgba(12,29,127,.75);
  --ma-hl:#FFFFFF;
  --ma-hl-halo:#0C1D7F;
  --ma-pill-ring:rgba(255,255,255,.38);
  --ma-st-ink:color-mix(in srgb,color-mix(in srgb,#0C1D7F 3%,#FFFFFF) 28%,transparent);
  --ma-leader:color-mix(in srgb,color-mix(in srgb,#0C1D7F 3%,#FFFFFF) 55%,transparent);
  --ma-shadow:rgba(12,29,127,.55);
  --ma-sans:"General Sans",sans-serif;
  color-scheme: dark;
}
@media (prefers-color-scheme: light) {
}
.ma {
  max-width: 1480px;
  margin: 0 auto;
  padding-inline: clamp(16px, 2.4vw, 32px);
  padding-block: clamp(18px, 2.4vw, 30px) 26px;
  color: var(--ma-ink);
  font-family: var(--ma-sans);
}
.ma *,
.ma *::before,
.ma *::after {
  box-sizing: border-box;
}
.ma [hidden] {
  display: none !important;
}
.ma-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
  gap: 14px 40px;
  margin-bottom: clamp(14px, 1.8vw, 20px);
}
.ma-head > div {
  min-width: 0;
}
.ma-kicker {
  margin: 0 0 8px;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 10px;
  font-size: 11.5px;
  font-weight: 620;
  letter-spacing: .15em;
  text-transform: uppercase;
  color: var(--ma-mute);
}
.ma-tag {
  padding: 2px 8px;
  border-radius: 999px;
  box-shadow: inset 0 0 0 1px var(--ma-line-2);
  font-size: 10.5px;
  letter-spacing: .06em;
  color: var(--ma-mute);
}
.ma-title {
  margin: 0;
  font-size: clamp(27px, 3.2vw, 42px);
  line-height: 1.03;
  font-weight: 760;
  font-stretch: 110%;
  letter-spacing: -.015em;
  text-wrap: balance;
}
.ma-lede {
  margin: 10px 0 0;
  max-width: 62ch;
  font-size: 15px;
  line-height: 1.45;
  color: var(--ma-mute);
}
.ma-lede .t {
  display: none;
}
@media (hover: none) and (pointer: coarse) {
  .ma-lede .h {
    display: none;
  }
  .ma-lede .t {
    display: inline;
  }
}
.ma-side {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 12px;
}
.ma-sum {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px 22px;
  font-size: 13.5px;
  color: var(--ma-mute);
}
.ma-sum li {
  display: flex;
  align-items: center;
  gap: 7px;
  white-space: nowrap;
}
.ma-sum b {
  color: var(--ma-ink);
  font-weight: 720;
  font-variant-numeric: tabular-nums;
}
.ma-ic {
  flex: none;
  display: inline-grid;
  place-items: center;
  width: 20px;
  height: 20px;
  border-radius: 50%;
}
.ma-ic svg {
  width: 12px;
  height: 12px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.1;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.ma-ic.a {
  background: var(--ma-navy);
  color: #FFFFFF;
  box-shadow: 0 0 0 1.5px var(--ma-pill-ring);
}
.ma-ic.b {
  background: #FFFFFF;
  color: var(--ma-navy);
  box-shadow: 0 0 0 1.5px var(--ma-navy);
}
.ma-tema {
  display: inline-flex;
  padding: 3px;
  gap: 2px;
  border-radius: 999px;
  background: var(--ma-raise);
  box-shadow: inset 0 0 0 1px var(--ma-line);
}
.ma-tema button {
  appearance: none;
  border: 0;
  margin: 0;
  padding: 5px 12px;
  border-radius: 999px;
  background: transparent;
  color: var(--ma-mute);
  font: inherit;
  font-size: 12.5px;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.ma-tema button svg {
  width: 13px;
  height: 13px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
}
.ma-tema button[aria-pressed=true] {
  background: var(--ma-surface);
  color: var(--ma-ink);
  box-shadow: 0 1px 3px var(--ma-shadow), inset 0 0 0 1px var(--ma-line);
}
.ma-tema button:focus-visible {
  outline: 2px solid var(--ma-ink);
  outline-offset: 2px;
}
@media (max-width: 899.98px) {
  .ma-head {
    grid-template-columns: minmax(0, 1fr);
  }
  .ma-side {
    align-items: flex-start;
  }
  .ma-sum {
    justify-content: flex-start;
  }
}
.ma-stage {
  position: relative;
}
.ma-view {
  position: relative;
  height: clamp(520px, calc(100vh - 230px), 860px);
  height: clamp(520px, calc(100dvh - 230px), 860px);
  border-radius: 16px;
  overflow: hidden;
  background: var(--ma-bg);
  isolation: isolate;
  box-shadow: inset 0 0 0 1px var(--ma-line);
}
.ma-map {
  position: absolute;
  inset: 0;
}
.ma .leaflet-container {
  background: transparent;
  font: inherit;
  font-family: var(--ma-sans);
}
.ma .leaflet-container a {
  color: var(--ma-mute);
}
.ma .leaflet-interactive {
  cursor: pointer;
}
.ma .leaflet-control-attribution {
  margin: 0 0 10px 10px !important;
  padding: 3px 8px;
  border-radius: 6px;
  background: var(--ma-bg-glass);
  color: var(--ma-faint);
  font-size: 10.5px;
  line-height: 1.4;
}
.ma .leaflet-control-attribution a {
  color: var(--ma-mute);
  text-decoration: none;
}
.ma .leaflet-control-attribution a:hover {
  color: var(--ma-ink);
}
.ma-tiles {
  opacity: .9;
}
.ma-tiles.is-dark {
  opacity: .78;
  filter: grayscale(1) invert(1) brightness(.74) contrast(1.06) sepia(.1) hue-rotate(140deg) saturate(.6);
}
.ma-mk {
  width: 0 !important;
  height: 0 !important;
}
.ma-pin {
  position: absolute;
  left: -11px;
  top: -29px;
  width: 22px;
  height: 29px;
  transform-origin: 50% 100%;
  transition: transform .16s ease;
  filter: drop-shadow(0 1px 2px rgba(12,29,127,.35));
}
.ma-pin svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}
.ma-pin .b {
  stroke-width: 1.8;
}
.ma-pin .i {
  fill: none;
  stroke-width: 2.3;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.ma-pin.a .b {
  fill: var(--ma-navy);
  stroke: #FFFFFF;
}
.ma-pin.a .i {
  stroke: #FFFFFF;
}
.ma-pin.b .b {
  fill: #FFFFFF;
  stroke: var(--ma-navy);
}
.ma-pin.b .i {
  stroke: var(--ma-navy);
}
.ma-pill {
  position: absolute;
  top: -29px;
  padding: 2px 8px 3px;
  border-radius: 999px;
  white-space: nowrap;
  background: var(--ma-navy);
  color: #FFFFFF;
  box-shadow: 0 0 0 1px var(--ma-pill-ring), 0 1px 3px rgba(12,29,127,.3);
  font-size: 11.5px;
  line-height: 15px;
  font-weight: 700;
  font-stretch: 92%;
  letter-spacing: .005em;
  transition: opacity .16s ease;
}
.ma-pill[data-side=r] {
  left: 14px;
}
.ma-pill[data-side=l] {
  right: 14px;
}
.ma-pill[data-side=t] {
  top: -52px;
  left: 0;
  transform: translateX(-50%);
}
.ma-pill[data-side=b] {
  top: 4px;
  left: 0;
  transform: translateX(-50%);
}
.ma-pill.is-off {
  opacity: 0;
  visibility: hidden;
}
.ma-mk.is-active .ma-pin {
  transform: scale(1.22);
}
.ma-mk.is-active .ma-pill {
  opacity: 1;
  visibility: visible;
  box-shadow: 0 0 0 2px var(--ma-hl), 0 2px 8px var(--ma-shadow);
}
.ma-has-active .ma-mk:not(.is-active) .ma-pill {
  opacity: .6;
}
.ma-has-active .ma-mk:not(.is-active) .ma-pill.is-off {
  opacity: 0;
}
.ma-st {
  position: absolute;
  left: 0;
  top: 0;
  transform: translate(-50%, -50%);
  white-space: nowrap;
  pointer-events: none;
  font-size: 10.5px;
  font-weight: 640;
  font-stretch: 118%;
  letter-spacing: .26em;
  text-transform: uppercase;
  color: var(--ma-st-ink);
}
.ma-st.is-off,
.ma-wl.is-off {
  visibility: hidden;
}
.ma-wl {
  position: absolute;
  left: 0;
  top: 0;
  white-space: nowrap;
  pointer-events: none;
  font-size: 11px;
  font-style: italic;
  font-weight: 560;
  letter-spacing: .04em;
  color: var(--ma-water-ink);
}
.ma-ctrl {
  position: absolute;
  top: 12px;
  left: 12px;
  z-index: 500;
  display: grid;
  gap: 6px;
}
.ma-btn {
  appearance: none;
  border: 0;
  margin: 0;
  padding: 0;
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: var(--ma-bg-glass);
  box-shadow: inset 0 0 0 1px var(--ma-line-2);
  color: var(--ma-ink);
  cursor: pointer;
  transition: background .15s;
}
.ma-btn:hover {
  background: var(--ma-raise);
}
.ma-btn:focus-visible {
  outline: 2px solid var(--ma-ink);
  outline-offset: 2px;
}
.ma-btn svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}
@media (hover: none) and (pointer: coarse) {
  .ma-btn[data-act=in],
  .ma-btn[data-act=out] {
    display: none;
  }
}
.ma-hint {
  position: absolute;
  inset: 0;
  z-index: 520;
  display: grid;
  place-items: center;
  pointer-events: none;
  opacity: 0;
  transition: opacity .2s;
}
.ma-hint span {
  padding: 9px 14px;
  border-radius: 10px;
  background: var(--ma-bg-glass);
  box-shadow: inset 0 0 0 1px var(--ma-line-2);
  font-size: 13.5px;
  color: var(--ma-ink);
}
.ma-hint.is-on {
  opacity: 1;
}
.ma-err {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 24px;
  text-align: center;
  color: var(--ma-mute);
  font-size: 14px;
}
.ma-card {
  position: absolute;
  left: 0;
  top: 0;
  z-index: 600;
  width: min(318px, calc(100% - 24px));
  padding: 14px 16px 13px;
  border-radius: 14px;
  background: var(--ma-surface);
  box-shadow:
    inset 0 0 0 1px var(--ma-line-2),
    0 22px 50px var(--ma-shadow),
    0 2px 8px var(--ma-shadow);
  pointer-events: none;
  opacity: 0;
  visibility: hidden;
  transform: translate3d(var(--x,0px), var(--y,0px), 0) scale(.98);
  transition:
    opacity .14s ease,
    transform .22s cubic-bezier(.2, .7, .2, 1),
    visibility 0s linear .14s;
}
.ma-card.is-on {
  opacity: 1;
  visibility: visible;
  transform: translate3d(var(--x,0px), var(--y,0px), 0);
  transition:
    opacity .14s ease,
    transform .22s cubic-bezier(.2, .7, .2, 1),
    visibility 0s;
}
.ma-card.is-pinned {
  pointer-events: auto;
}
.ma-card.no-anim {
