  stroke-width: 2.3;
}
.ma .ma-native-markers {
  position: absolute;
  inset: 0;
  pointer-events: none;
  display: none;
}
.ma[data-map-ready=true] .ma-native-markers {
  display: block;
}
.ma .ma-native-marker {
  position: absolute;
  z-index: 2;
  width: 44px;
  height: 44px;
  min-width: 44px;
  min-height: 44px;
  transform: translate(-50%, -34px);
  border: 0;
  border-radius: 12px;
  background: transparent;
  padding: 0;
  color: #0C1D7F;
  pointer-events: auto;
  touch-action: manipulation;
  cursor: pointer;
}
.ma .ma-native-pin {
  position: absolute;
  left: 11px;
  top: 5px;
  width: 22px;
  height: 29px;
  filter: drop-shadow(0 1px 2px #0C1D7F45);
