  stroke-width: 1.8;
}
.ma .ma-native-pin circle {
  fill: none;
}
.ma .ma-native-marker.is-active {
  z-index: 5;
}
.ma .ma-native-marker.is-active .ma-native-pin svg {
  fill: #80D7D9;
  stroke: #0C1D7F;
}
.ma .ma-native-label {
  position: absolute;
  padding: 4px 8px;
  border-radius: 12px;
  background: #0C1D7F;
  color: #FFFFFF;
  font-size: 12px;
  font-weight: 600;
  line-height: 16px;
  white-space: nowrap;
  pointer-events: none;
}
.ma .ma-native-marker.is-active .ma-native-label {
  background: #80D7D9;
  color: #0C1D7F;
}
.ma .ma-native-marker:focus-visible {
  outline: 3px solid #80D7D9;
  outline-offset: 1px;
}
.ma .ma-native-marker:focus-visible .ma-native-pin svg {
  fill: #80D7D9;
}
.ma .ma-native-state,
.ma .ma-native-water-label {
  position: absolute;
  transform: translate(-50%, -50%);
  white-space: nowrap;
  pointer-events: none;
  font-size: 11px;
  color: #0C1D7F;
  letter-spacing: .15em;
