}
.ma .ma-native-water-label {
  font-size: 11px;
  color: #0C1D7F;
  font-style: italic;
  text-transform: none;
  letter-spacing: 0;
}
.ma .ma-btn:disabled {
  opacity: .45;
  cursor: default;
  transform: none;
}
.ma .ma-hint {
  display: none;
}
.ma .ma-card {
  pointer-events: auto;
}
.ma .ma-list {
  min-width: 0;
}
.ma .ma-map:focus-visible {
  outline: 3px solid #80D7D9;
  outline-offset: -3px;
}
.ma.ma-gesturing .ma-map {
