}
.ma.ma-gesturing .ma-native-label {
  display: none;
}
@media (max-width: 959.98px) {
  .ma .ma-btn[data-act] {
    display: grid;
  }
  .ma .ma-card.is-on {
    transform: none;
  }
  .ma .ma-native-marker {
    width: 44px;
    height: 44px;
  }
  .ma .ma-ctrl {
    gap: 8px;
  }
  .ma .ma-native-label {
    font-size: 11px;
    line-height: 15px;
  }
  .ma .ma-lede .h {
    display: none;
  }
  .ma .ma-lede .t {
    display: inline;
  }
}
.ma .ma-native-marker--pole .ma-native-pin svg {
  fill: #0C1D7F;
  stroke: #FFFFFF;
}
.ma .ma-native-marker--pole .ma-native-label {
  border: 1px solid #FFFFFF;
}
.ma .ma-native-label small {
  display: block;
  font-size: 10px;
  line-height: 13px;
  color: inherit;
  font-weight: 600;
  letter-spacing: 0;
}
.ma .ma-pole-legend {
  position: absolute;
  left: 16px;
  bottom: 12px;
  max-width: calc(100% - 308px);
  z-index: 3;
  background: #FFFFFF;
  color: #0C1D7F;
  border: 1px solid #80D7D966;
  border-radius: 10px;
  padding: 10px 12px;
  margin: 0;
  display: flex;
  gap: 8px;
  align-items: center;
