}
.ma .ma-pole-legend span {
  display: inline-flex;
  flex: 0 0 20px;
}
.ma .ma-pole-legend svg {
  width: 20px;
  height: 20px;
  fill: #0C1D7F;
  stroke: #FFFFFF;
}
@media (max-width: 959.98px) {
  .ma .ma-pole-legend {
    left: 10px;
    right: 10px;
    bottom: 8px;
    max-width: none;
    font-size: 12px;
    padding: 8px;
  }
  .ma .ma-native-label small {
    font-size: 9px;
    line-height: 12px;
  }
}

/* revision.css */
/* VITA Sertão — official palette and layout revision, 13 October 2026. */
:root {
  --vita-official-blue: #0C1D7F;
  --vita-official-turquoise: #80D7D9;
  --vita-official-white: #FFFFFF;
  --vita-official-accent: #80D7D9;
  --vita-official-focus: #80D7D9;
  --vita-support-blue: #003BA8;
  --vita-support-turquoise: #60CCCF;
  --brand-navy: var(--vita-official-blue);
  --brand-accent: var(--vita-official-accent);
  --brand-gradient: linear-gradient(125deg, #003BA8, #0C1D7F 76%);
  --vita-blue: var(--vita-official-blue);
  --vita-navy: var(--vita-official-blue);
  --vita-dark: var(--vita-official-blue);
  --vita-deep: var(--vita-official-blue);
  --vita-accent: var(--vita-official-accent);
  --vita-turquoise: var(--vita-official-turquoise);
  --vita-gradient: var(--brand-gradient);
  --vita-gradient-dark: var(--brand-gradient);
  --s-blue: var(--vita-official-blue);
}
html {scroll-behavior: smooth; scrollbar-gutter: stable;}
body.vita-redesign {background: #FFFFFF; color: #0C1D7F;}
body.vita-redesign *, body.vita-redesign *::before, body.vita-redesign *::after {box-sizing: border-box;}
body.vita-redesign :is(main, section, article, aside, header, footer, div, figure, form) {min-width: 0;}
body.vita-redesign :is(h1,h2,h3,h4,p,li,dd,dt,a,button,label,summary) {overflow-wrap: break-word;}
body.vita-redesign :is(img,video,canvas) {max-width: 100%;}
body.vita-redesign main p {font-weight: 500;}
body.vita-redesign .s-container,
body.vita-redesign .vs-inst-container,
body.vita-redesign .vs-qs-container {width: min(1240px, calc(100% - 48px)); margin-inline: auto;}
body.vita-redesign :is(.s-container,.vs-inst-container,.vs-qs-container) :is(.s-container,.vs-inst-container,.vs-qs-container) {width: 100%; padding-inline: 0;}
body.vita-redesign :is(.v-button,.vs-inst-button,.vs-inst-btn,.vs-qs-button) {
  display: inline-flex; align-items: center; justify-content: center; gap: 12px;
  min-height: 48px; padding: 13px 20px; max-width: 100%;
  border-radius: 12px; background: #0C1D7F; color: #FFFFFF;
  border: 1px solid transparent; line-height: 1.4; white-space: normal;
  text-decoration: none; font-weight: 600; box-shadow: none;
}
body.vita-redesign :is(.v-button,.vs-inst-button,.vs-inst-btn,.vs-qs-button):hover {
  background: #80D7D9 !important; color: #0C1D7F !important; border-color: #80D7D9 !important;
}
body.vita-redesign .v-button--aqua {background: #80D7D9; color: #0C1D7F;}
body.vita-redesign .v-button--aqua:hover {background: #80D7D9 !important; border-color: #80D7D9 !important;}
body.vita-redesign :is(a,button,summary,input,select,textarea):focus-visible {outline: 3px solid #80D7D9; outline-offset: 4px;}
body.vita-redesign .brand-utility {background: #0C1D7F;}
body.vita-redesign .brand-utility .brand-service {background: #80D7D9; color: #0C1D7F;}
body.vita-redesign .brand-mega--two {grid-template-columns: repeat(2,minmax(0,1fr));}
body.vita-redesign .brand-header .brand-nav-investors {font-weight: 600; font-size: 14px;}
body.vita-redesign .brand-mega-column h2 {color: #0C1D7F; font-size: 18px; margin-bottom: 14px;}
body.vita-redesign .brand-mega-column a {color: #0C1D7F;}
body.vita-redesign .brand-nav summary::after {display: none;}
body.vita-redesign .brand-nav summary .v-icon {width: 15px; height: 15px; flex: 0 0 15px;}
body.vita-redesign .brand-header .brand-nav > :is(details,a) {min-width: 0;}
body.vita-redesign .brand-nav > details > summary {padding-inline: 9px; font-size: 13px !important; gap: 4px;}
body.vita-redesign .brand-nav > .brand-nav-investors {font-size: 13px !important; padding-inline: 9px;}
body.vita-redesign .brand-mega-column {min-width: 0;}
body.vita-redesign .brand-nav > details:hover > summary,
body.vita-redesign .brand-nav > details[open] > summary,
body.vita-redesign .brand-nav > a:hover {background: #80D7D9; color: #0C1D7F;}

/* Explicit surfaces prevent dark typography from leaking into blue sections. */
body.vita-redesign [data-vita-surface="blue"] {color: #FFFFFF;}
body.vita-redesign [data-vita-surface="blue"] :is(h1,h2,h3,h4,p,li,dt,dd,small,address,label,strong,span,a) {color: #FFFFFF !important;}
body.vita-redesign [data-vita-surface="blue"] :is(.s-tag,.vs-inst-kicker,.vs-qs-kicker) {color: #0C1D7F !important; background: #FFFFFF !important;}
body.vita-redesign [data-vita-surface="blue"] :is(input,select,textarea) {color: #0C1D7F; background: #FFFFFF;}
body.vita-redesign [data-vita-surface="light"] {background: #FFFFFF !important; color: #0C1D7F !important;}
body.vita-redesign [data-vita-surface="blue"] [data-vita-surface="light"] :is(h1,h2,h3,h4,p,li,dt,dd,small,address,label,strong,span,a),
body.vita-redesign [data-vita-surface="light"] :is(h1,h2,h3,h4,p,li,dt,dd,small,address,label,strong,span,a) {color: #0C1D7F !important;}
body.vita-redesign [data-vita-surface="blue"] :is(.v-button--aqua,.vs-inst-button--outline),
body.vita-redesign [data-vita-surface="blue"] :is(.v-button--aqua,.vs-inst-button--outline) * {color: #0C1D7F !important;}
body.vita-redesign [data-vita-surface="blue"] :is(.v-button--aqua) {background: #80D7D9 !important;}
body.vita-redesign [data-vita-surface="light"] :is(.v-button,.vs-inst-button,.vs-inst-btn,.vs-qs-button),
body.vita-redesign [data-vita-surface="light"] :is(.v-button,.vs-inst-button,.vs-inst-btn,.vs-qs-button) * {color: #FFFFFF !important;}
body.vita-redesign [data-vita-surface="light"] :is(.v-button,.vs-inst-button,.vs-inst-btn,.vs-qs-button):hover,
body.vita-redesign [data-vita-surface="light"] :is(.v-button,.vs-inst-button,.vs-inst-btn,.vs-qs-button):hover * {color: #0C1D7F !important;}
body.vita-redesign .vita-page-hero .vita-page-lead {color: #FFFFFF !important; font-weight: 600; max-width: 62ch;}
body.vita-redesign .vita-page-copy :is(h1,p) {text-wrap: pretty;}
body.vita-redesign .vita-page-hero--compact {padding-block: clamp(30px,4vw,58px);}
body.vita-redesign .vita-page-hero--compact h1 {max-width: 27ch; margin-bottom: 18px; font-size: clamp(32px,3.6vw,52px);}
body.vita-redesign .vita-store-return {margin-top: 12px;}
body.vita-redesign .s-hero {margin: 0; padding: 0; background: #0C1D7F;}
body.vita-redesign :is(.brand-about,.brand-numbers,.brand-colored-section,.brand-footer,.vita-page-hero,.vs-inst-band) {background-image: var(--brand-gradient);}

/* Service store and detailed pages use content-driven grids and flex rows. */
.vita-anchor {display: block; scroll-margin-top: 130px;}
.vita-store-tabs {display: flex; flex-wrap: wrap; gap: 12px; padding-block: 26px; border-bottom: 1px solid #80D7D980;}
.vita-store-tabs a {display: inline-flex; align-items: center; justify-content: center; min-height: 46px; padding: 11px 18px; border-radius: 12px; background: #80D7D933; color: #0C1D7F; text-decoration: none; font-weight: 600;}
.vita-store-tabs a:hover {background: #80D7D9;}
.vita-store-section {padding-block: clamp(32px,4vw,52px);}
.vita-store-section + .vita-store-section {border-top: 1px solid #80D7D980;}
.vita-store-section .vita-section-heading {margin-bottom: 24px; max-width: 72ch;}
.vita-store-section .vita-section-heading p:last-child {margin-bottom: 0;}
.vita-store-grid {display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 24px; align-items: stretch;}
#atendimento .vita-store-grid {grid-template-columns: repeat(2,minmax(0,1fr));}
.vita-store-card {display: flex; flex-direction: column; align-items: flex-start; gap: 14px; min-width: 0; height: auto; padding: 28px; border: 1px solid #80D7D980; border-radius: 22px; background: #FFFFFF; color: #0C1D7F; text-decoration: none; transition: transform .2s,border-color .2s,box-shadow .2s;}
.vita-store-card .brand-icon {width: 78px; height: 78px; object-fit: contain;}
.vita-store-card h3 {font-size: 23px; line-height: 1.25; margin: 0; color: #0C1D7F;}
body.vita-redesign .vita-store-card p {font-size: 17px; line-height: 1.6; color: #0C1D7F; margin: 0; font-weight: 500;}
.vita-store-card-action {display: flex; justify-content: space-between; align-items: center; gap: 18px; width: 100%; padding-top: 20px; margin-top: auto; border-top: 1px solid #80D7D980; font-weight: 600; color: #0C1D7F;}
.vita-store-card:hover {transform: translateY(-4px); border-color: #0C1D7F; box-shadow: 0 10px 28px #0C1D7F12;}
.vita-store-card:hover .vita-store-card-action .v-icon {transform: translateX(3px);}
.vita-service-page .vita-service-content {display: block; border: 0; border-radius: 0; background: #FFFFFF; padding-block: 24px;}
.vita-service-page .vita-service-content > section {padding-block: 20px !important;}
.vita-service-page .vita-service-content .vs-inst-head h2 {display: block;}
.vita-service-page .vita-store-back {display: flex; align-items: center; justify-content: space-between; gap: 28px; margin-block: 32px 48px; padding: 30px; border: 1px solid #80D7D980; border-radius: 22px; background: #80D7D91A;}
.vita-store-back > div {max-width: 68ch;}
.vita-store-back h2 {font-size: clamp(26px,2.6vw,34px); line-height: 1.2; margin: 14px 0;}
.vita-store-back p {margin-block: 0;}
.vita-store-back .v-button {flex: 0 0 auto;}
.vita-service-request {padding: 28px; border: 1px solid #80D7D980; border-radius: 22px; background: #FFFFFF; display: flex; flex-direction: column; align-items: flex-start; gap: 18px;}
.vita-service-request h3 {font-size: 26px; margin: 0;}
.vita-service-request p {margin: 0; max-width: 72ch;}
.vita-request-content {padding-block: 42px;}

/* Consistent cards, editorial rows and clear typographic hierarchy. */
body.vita-redesign main :is(.vs-inst-grid,.vs-inst-cards,.vs-qs-mvv-grid,.vs-serv-pay,.vs-serv-ways,.vs-serv-channels,.vs-serv-categories,.vs-lojas__list,.vs-sust-pilares,.vs-sust-links__grid,.vs-post-grid,.v-extra-grid,.vita-service-requests) {display: grid; grid-template-columns: repeat(auto-fit,minmax(min(100%,280px),1fr)); gap: 24px; align-items: stretch;}
body.vita-redesign main :is(.vs-inst-card,.vs-qs-card,.vs-sust-card,.vs-inst-cards > li,.vs-serv-channel,.vs-serv-way,.vs-serv-pay > div,.vita-service-requests > article) {width: auto; min-width: 0; height: auto; margin: 0; padding: 26px; border: 1px solid #80D7D980; border-radius: 20px; background: #FFFFFF; color: #0C1D7F; box-shadow: none; display: flex; flex-direction: column; align-items: flex-start; gap: 14px;}
body.vita-redesign main :is(.vs-inst-card,.vs-qs-card,.vs-sust-card,.vs-inst-cards > li,.vs-serv-channel,.vs-serv-way,.vs-serv-pay > div) :is(h3,h4,p) {margin: 0; color: #0C1D7F;}
body.vita-redesign main :is(.vs-inst-card,.vs-inst-cards > li,.vs-serv-channel) :is(.v-button,.vs-inst-button,.vs-inst-btn) {margin-top: auto;}
body.vita-redesign main .vs-inst-cards__icon {flex: 0 0 auto; width: 48px; height: 48px; display: grid; place-items: center; border-radius: 14px; background: #80D7D94D !important; color: #0C1D7F !important;}
body.vita-redesign main .vs-inst-cards__icon svg {width: 28px; height: 28px;}
body.vita-redesign main :is(.vs-inst-split,.vita-activity-grid,.vita-resource-grid,.vs-qs-intro-grid) {display: grid; grid-template-columns: minmax(0,.9fr) minmax(0,1.1fr); gap: clamp(24px,4vw,48px); align-items: start;}
body.vita-redesign main :is(.vs-inst-split__head,.vs-inst-split__body,.vita-page-copy,.vita-prose,.vs-inst-prose) {min-width: 0;}
body.vita-redesign main :is(.vs-inst-highlight,.vs-serv-step__card,.vs-serv-vulneravel,.vs-serv-contract__card) {padding: 24px; border: 1px solid #80D7D980; border-radius: 20px; box-shadow: none; height: auto;}
body.vita-redesign main .vs-inst-highlight {background: #FFFFFF; border-left: 5px solid #80D7D9; display: flex; align-items: flex-start; gap: 18px;}
body.vita-redesign main .vs-inst-highlight p {margin: 0;}
body.vita-redesign main .vs-serv-tiers {display: grid; grid-template-columns: repeat(4,minmax(0,1fr)); align-items: end; gap: 12px; color: #FFFFFF;}
body.vita-redesign main .vs-serv-tiers__bar {background: #0C1D7F; color: #FFFFFF !important; display: flex; align-items: center; justify-content: center; min-height: 62px; padding: 14px 8px; height: calc(58px + var(--tier,1)*24px); border-radius: 14px 14px 4px 4px;}
body.vita-redesign main .vs-serv-tiers__bar b {color: #FFFFFF !important;}
body.vita-redesign .brand-content-fold > summary {background: #FFFFFF; color: #0C1D7F;}
body.vita-redesign .brand-content-fold[open] > summary {background: #0C1D7F; color: #FFFFFF;}
body.vita-redesign .brand-content-fold > summary:hover,
body.vita-redesign .brand-content-fold[open] > summary:hover {background: #80D7D9; color: #0C1D7F;}
body.vita-redesign .brand-content-fold[open] > summary:hover::after {color: #0C1D7F;}
body.vita-redesign .vita-service-content .brand-content-fold {border: 1px solid #80D7D980; border-radius: 16px; margin-block: 20px; overflow: hidden;}
body.vita-redesign .vita-service-content .brand-content-fold > summary {padding: 20px;}
body.vita-redesign .vs-inst-nav ul,
body.vita-redesign .vs-qs-nav ul {display: flex; flex-wrap: wrap; gap: 10px;}
body.vita-redesign .vs-inst-nav a,
body.vita-redesign .vs-qs-nav a {white-space: normal; min-height: 44px;}
body.vita-redesign .vs-qs-facts {padding: 28px; border-radius: 22px; background: #80D7D933 !important;}
body.vita-redesign .vs-qs-facts :is(dt,dd) {color: #0C1D7F;}
body.vita-redesign .vs-qs-facts dl {margin: 0; display: grid; gap: 22px;}
body.vita-redesign .vs-qs-facts dd {margin: 6px 0 0; line-height: 1.55;}
body.vita-redesign .vs-qs-goals {display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 20px; padding: 24px;}
body.vita-redesign .vita-goal {min-width: 0; height: auto; display: flex; align-items: flex-start; gap: 20px; padding: 20px; border: 1px solid #80D7D980; border-radius: 18px;}
body.vita-redesign .vita-goal .brand-icon {width: 72px; height: 72px; flex: 0 0 72px;}
body.vita-redesign .vita-goal p {margin: 8px 0 0;}
body.vita-redesign .vita-responsibilities {background: #80D7D91A; border-color: #80D7D980;}
body.vita-redesign .brand-footer .s-footer-sitemap a {color: #FFFFFF !important;}
body.vita-redesign .brand-footer .s-footer-attend {background: #FFFFFF; color: #0C1D7F;}
body.vita-redesign .brand-footer .s-footer-attend :is(h2,h3,p,a,span,small,strong) {color: #0C1D7F !important;}
body.vita-redesign .brand-footer .s-footer-sitemap a:hover {color: #80D7D9 !important;}
body.vita-redesign .brand-about .vita-stats {gap: 22px;}
body.vita-redesign .brand-services {gap: 18px;}
body.vita-redesign .brand-services > a {background: #FFFFFF; border-color: #80D7D980; min-height: 170px; padding: 20px;}
body.vita-redesign .brand-services > a:hover {background: #80D7D9;}
body.vita-redesign .brand-services span {color: #0C1D7F;}

@media (max-width: 1100px) {
  body.vita-redesign .brand-navrow {padding-inline: 16px; gap: 10px;}
  body.vita-redesign .brand-header .v-brand {flex-basis: 128px;}
  body.vita-redesign .brand-header .v-brand img {width: 128px; height: 55px;}
  body.vita-redesign .brand-nav > details > summary {padding-inline: 7px; font-size: 12px !important;}
  body.vita-redesign .brand-nav > .brand-nav-investors {padding-inline: 7px; font-size: 12px !important;}
}
@media (max-width: 960px) {
  body.vita-redesign .brand-mega--two {grid-template-columns: minmax(0,1fr);}
  body.vita-redesign .brand-mega-column {padding: 0; border: 0;}
  body.vita-redesign .brand-mega-column + .brand-mega-column {margin-top: 20px; padding-top: 18px; border-top: 1px solid #80D7D980;}
  body.vita-redesign .brand-nav > details > summary,
  body.vita-redesign .brand-nav > .brand-nav-investors {font-size: 16px !important; padding: 14px 16px; min-height: 52px;}
  body.vita-redesign .brand-nav > .brand-nav-investors {width: 100%;}
  body.vita-redesign main :is(.vs-inst-split,.vita-activity-grid,.vita-resource-grid,.vs-qs-intro-grid) {grid-template-columns: minmax(0,1fr); gap: 24px;}
  .vita-store-grid {grid-template-columns: repeat(2,minmax(0,1fr)); gap: 20px;}
  body.vita-redesign .vita-store-back {align-items: flex-start; flex-direction: column; gap: 22px;}
  body.vita-redesign .vs-qs-goals {grid-template-columns: minmax(0,1fr);}
}
@media (max-width: 600px) {
  body.vita-redesign .s-container,
  body.vita-redesign .vs-inst-container,
  body.vita-redesign .vs-qs-container {width: calc(100% - 32px);}
  body.vita-redesign :is(.s-container,.vs-inst-container,.vs-qs-container) :is(.s-container,.vs-inst-container,.vs-qs-container) {width: 100%;}
  body.vita-redesign .brand-utility-inner {padding-inline: 16px;}
  body.vita-redesign .brand-utility .brand-service {min-height: 44px; padding-inline: 12px;}
  body.vita-redesign .v-header.brand-header {width: calc(100% - 24px);}
  .vita-store-grid, #atendimento .vita-store-grid {grid-template-columns: minmax(0,1fr); gap: 16px;}
  .vita-store-tabs {gap: 8px; padding-block: 18px;}
  .vita-store-tabs a {flex: 1 1 auto; padding-inline: 12px; font-size: 15px;}
  .vita-store-section {padding-block: 30px;}
  .vita-store-card {padding: 22px; gap: 12px;}
  .vita-store-card .brand-icon {width: 64px; height: 64px;}
  .vita-store-card h3 {font-size: 22px;}
  body.vita-redesign .vita-store-card p {font-size: 16px;}
  body.vita-redesign .vita-store-back {padding: 22px; margin-block: 24px 32px;}
  body.vita-redesign .vita-store-back .v-button,
  body.vita-redesign .vita-store-return {width: 100%;}
  body.vita-redesign main :is(.vs-inst-grid,.vs-inst-cards,.vs-qs-mvv-grid,.vs-serv-pay,.vs-serv-ways,.vs-serv-channels,.vs-serv-categories,.vs-lojas__list,.vs-sust-pilares,.vs-sust-links__grid,.vs-post-grid,.v-extra-grid,.vita-service-requests) {grid-template-columns: minmax(0,1fr); gap: 16px;}
  body.vita-redesign main :is(.vs-inst-card,.vs-qs-card,.vs-sust-card,.vs-inst-cards > li,.vs-serv-channel,.vs-serv-way,.vs-serv-pay > div,.vita-service-requests > article,.vs-inst-highlight,.vs-serv-step__card,.vs-serv-vulneravel,.vs-serv-contract__card) {padding: 20px;}
  body.vita-redesign main .vs-serv-tiers {gap: 8px;}
  body.vita-redesign main .vs-serv-tiers__bar {font-size: 13px; padding-inline: 4px;}
  body.vita-redesign .vita-goal {padding: 18px; gap: 14px;}
  body.vita-redesign .vita-goal .brand-icon {width: 56px; height: 56px; flex-basis: 56px;}
  body.vita-redesign .vs-qs-facts {padding: 22px;}
  body.vita-redesign .brand-footer .s-footer-main {gap: 26px;}
}
@media (prefers-reduced-motion: reduce) {
  html {scroll-behavior: auto;}
  body.vita-redesign *, body.vita-redesign *::before, body.vita-redesign *::after {animation-duration: .01ms !important; transition-duration: .01ms !important;}
}

body.vita-redesign .vita-service-page .vs-serv-pay {grid-template-columns: minmax(0,1fr);}
body.vita-redesign .vita-service-page .vs-serv-pay > div {grid-column: 1 / -1;}
body.vita-redesign .vita-service-page .vs-serv-pay__icon {position: static; display: none;}
body.vita-redesign .vs-serv-ways > li {min-width: 0; padding: 20px; border: 1px solid #80D7D980; border-radius: 18px; background: #FFFFFF; display: flex; align-items: flex-start; gap: 14px;}
body.vita-redesign .vs-serv-ways__icon {flex: 0 0 40px; color: #0C1D7F;}

/* Carousel text retains sufficient contrast on the official blue. */
body.vita-redesign .s-hero :is(.campaign-title,.campaign-description,.campaign-closing,.campaign-contact-links a) {color: #FFFFFF !important;}
body.vita-redesign .s-hero .campaign-label {color: #0C1D7F !important; background: #FFFFFF !important;}
body.vita-redesign .s-carousel-bar :is(span,button) {color: #FFFFFF !important;}
body.vita-redesign .s-carousel-bar button:hover, body.vita-redesign .s-carousel-bar button:hover span {color: #0C1D7F !important; background: #80D7D9;}
@media (max-width: 760px) {body.vita-redesign .campaign-title {font-size: clamp(29px,5.5vw,38px) !important; line-height: 1.15; max-width: 100%;}}

body.vita-redesign .brand-footer .s-footer-attend > a {display: grid; grid-template-columns: 38px minmax(0,1fr) 20px; gap: 12px; align-items: center; min-height: 64px; width: 100%; height: auto; padding: 14px 12px; border-radius: 14px;}
body.vita-redesign .brand-footer .s-footer-attend .s-footer-icon {display: grid; place-items: center; width: 38px; height: 38px; border-radius: 11px; background: #80D7D94D;}
body.vita-redesign .brand-footer .s-footer-attend > a > span:nth-child(2) {display: flex; flex-direction: column; gap: 4px; min-width: 0;}
body.vita-redesign .brand-footer .s-footer-attend small {font-size: 12px; line-height: 1.4;}
body.vita-redesign .brand-footer .s-footer-attend strong {font-size: 16px; line-height: 1.4;}
body.vita-redesign .brand-footer .s-footer-attend > a > .v-icon {width: 20px; height: 20px;}

body.vita-redesign .s-hero .campaign-contact-links a {background: #FFFFFF; color: #0C1D7F !important;}
body.vita-redesign .s-hero .campaign-contact-links a :is(span,svg) {color: #0C1D7F !important;}
body.vita-redesign .s-hero .campaign-contact-links a:hover {background: #80D7D9;}

/* documento.css */
/* VITA Sertão: documento e canais oficiais, 13/10/2026. */
:root {
  --brand-accent: #80D7D9;
  --vita-accent: #80D7D9;
  --vita-official-accent: #80D7D9;
  --vita-official-focus: #80D7D9;
}
body.vita-redesign .v-button--aqua,
body.vita-redesign .v-button--aqua {background:#80D7D9; color:#0C1D7F;}
body.vita-redesign [data-vita-surface="blue"] :is(.v-button--aqua,.v-button--aqua),
body.vita-redesign [data-vita-surface="blue"] :is(.v-button--aqua,.v-button--aqua) * {color:#0C1D7F !important; background-color:#80D7D9;}
body.vita-redesign .vita-official-contact {display:flex; align-items:center; gap:10px; padding-block:8px;}
.vita-official-contact img {width:25px; height:25px; object-fit:contain;}
.vita-official-contact > span {display:grid; gap:1px;}
.vita-official-contact strong {font-size:15px; line-height:1.3; color:#FFFFFF;}
.vita-official-contact small {font-size:11px; line-height:1.35; color:#FFFFFF;}
.brand-utility-inner > nav {align-items:center; gap:18px;}
.vita-wa-float {
  position:fixed; z-index:900; right:max(22px,env(safe-area-inset-right));
  bottom:max(22px,env(safe-area-inset-bottom)); width:62px; height:62px;
  display:flex; align-items:center; justify-content:center; border-radius:50%;
  border:2px solid #FFFFFF; background:#0C1D7F; color:#FFFFFF;
  box-shadow:0 5px 22px #0C1D7F30; text-decoration:none;
  transition:transform .2s ease,box-shadow .2s ease;
}
.vita-wa-float img {display:block; width:34px; height:34px; object-fit:contain;}
.vita-wa-float::before {content:""; position:absolute; inset:-3px; border:2px solid #80D7D9; border-radius:50%; animation:vita-wa-pulse 2.8s ease-out infinite; pointer-events:none;}
.vita-wa-float:hover {transform:translateY(-3px); box-shadow:0 8px 24px #0C1D7F50;}
.vita-wa-float:focus-visible {outline:3px solid #80D7D9; outline-offset:5px;}
html.vita-menu-open .vita-wa-float {visibility:hidden;}
@keyframes vita-wa-pulse {0%{transform:scale(1);opacity:.65}75%,100%{transform:scale(1.35);opacity:0}}
.vita-document-page {background:#FFFFFF; color:#0C1D7F;}
.vita-document-page .vita-page-hero {padding-block:clamp(34px,4vw,64px);}
.vita-document-page .vita-page-hero h1 {font-size:clamp(32px,3.8vw,54px); max-width:24ch; line-height:1.12; text-wrap:balance;}
.vita-document-page .vita-page-lead {font-size:clamp(16px,1.35vw,19px); line-height:1.55; max-width:70ch;}
.vita-document-page .vita-page-photo {margin:0; aspect-ratio:4/3; min-height:0; overflow:hidden; border-radius:24px;}
.vita-document-page .vita-page-photo img {width:100%; height:100%; object-fit:cover;}
.vita-document-nav {display:flex; flex-wrap:wrap; gap:10px; padding-block:24px;}
.vita-document-nav a {padding:10px 15px; border:1px solid #80D7D9; border-radius:10px; color:#0C1D7F; background:#FFFFFF; font-size:15px; font-weight:600; text-decoration:none;}
.vita-document-nav a:hover {background:#80D7D9;}
.vita-document-section {padding:clamp(34px,4.5vw,64px) 0; color:#0C1D7F; background:#FFFFFF;}
.vita-document-section--tint {background:#80D7D91F;}
.vita-document-heading {margin:0 0 26px; max-width:83ch;}
.vita-document-heading h2 {font-size:clamp(26px,2.8vw,39px); line-height:1.2; margin:0 0 15px; text-wrap:balance; color:#0C1D7F;}
.vita-document-heading p {margin:0; line-height:1.65; color:#0C1D7F;}
.vita-document-section > .s-container > p {max-width:84ch;}
.vita-document-grid {display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); align-items:stretch; gap:22px;}
.vita-document-grid--four {grid-template-columns:repeat(4,minmax(0,1fr));}
.vita-document-grid--two {grid-template-columns:repeat(2,minmax(0,1fr));}
.vita-document-card,.vita-related-card {display:flex; flex-direction:column; align-items:flex-start; gap:15px; padding:27px; border:1px solid #80D7D980; border-radius:20px; background:#FFFFFF; color:#0C1D7F; min-width:0; text-decoration:none;}
.vita-document-card h3,.vita-related-card h3 {font-size:22px; line-height:1.3; margin:0; color:#0C1D7F; text-wrap:balance;}
.vita-document-card p,.vita-related-card p {font-size:16px; line-height:1.65; margin:0; color:#0C1D7F;}
.vita-document-card > .v-button {margin-top:auto;}
.vita-document-icon {width:48px; height:48px; border-radius:13px; background:#80D7D940; color:#0C1D7F; display:grid; place-items:center;}
.vita-document-icon svg {width:26px; height:26px;}
.vita-related-card {transition:transform .2s ease,border-color .2s ease;}
.vita-related-card:hover {transform:translateY(-3px); border-color:#0C1D7F;}
.vita-related-card > span {margin-top:auto; padding-top:16px; display:flex; align-items:center; justify-content:space-between; gap:12px; width:100%; font-weight:600; border-top:1px solid #80D7D980;}
.vita-document-fold {margin:20px auto; padding-bottom:0; width:100%; border-radius:0; border-inline:0; border-color:#80D7D9;}
.vita-document-fold > summary {width:min(1240px,calc(100% - 48px)); margin:auto; display:flex; justify-content:space-between; gap:20px; padding:26px 0; font-weight:700; font-size:clamp(24px,2.6vw,34px); color:#0C1D7F;}
.vita-document-fold > summary::after {display:none;}
.vita-document-fold > summary .v-icon {flex-shrink:0; width:24px; transition:transform .2s;}
.vita-document-fold[open] > summary .v-icon {transform:rotate(180deg);}
.vita-document-fold > .s-container {padding-bottom:34px;}
.vita-document-figure {margin:25px 0 32px; padding:18px; border:1px solid #80D7D980; border-radius:20px; background:#FFFFFF;}
.vita-document-figure img {display:block; width:100%; height:auto;}
.vita-document-steps {list-style:none; margin:0; padding:0; display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:18px;}
.vita-document-steps li {display:flex; gap:16px; align-items:flex-start; padding:24px; border:1px solid #80D7D980; border-radius:18px; background:#FFFFFF; color:#0C1D7F;}
.vita-step-number {width:42px; height:42px; min-width:42px; display:grid; place-items:center; border-radius:12px; background:#80D7D9; color:#0C1D7F; font-size:22px; font-weight:700;}
.vita-document-steps h3 {font-size:21px; line-height:1.3; margin:0 0 10px; color:#0C1D7F;}
.vita-document-steps p {font-size:16px; line-height:1.6; margin:0; color:#0C1D7F;}
.vita-process-group {margin:28px 0;}
.vita-process-group > h3 {font-size:18px; font-weight:700; padding:14px 20px; background:#0C1D7F; color:#FFFFFF; border-radius:12px; margin:0 0 18px;}
.vita-calculator-wrap {padding-block:34px;}
.vita-calculator-wrap .vs-oqf-calculator {margin:0; padding:32px; border:1px solid #80D7D9; border-radius:22px; background:#80D7D91F; color:#0C1D7F; display:grid; grid-template-columns:1fr 1.1fr; gap:32px;}
.vita-calculator-wrap .vs-oqf-calculator__notice {font-size:14px; margin-top:18px;}
.vita-calculator-wrap .vs-oqf-calculator__result {background:#0C1D7F; color:#FFFFFF;}
.vita-calculator-wrap .vs-oqf-calculator__result :is(p,output) {color:#FFFFFF !important;}
.vita-report-card {display:flex; align-items:center; justify-content:space-between; gap:26px; padding:28px; border:1px solid #80D7D9; border-radius:20px; background:#FFFFFF;}
.vita-report-card h3 {font-size:23px; margin:8px 0;}
.vita-report-card .v-button {flex-shrink:0;}
body.vita-redesign .vita-report-type {font-size:13px; font-weight:700; letter-spacing:.02em; margin:0; color:#0C1D7F;}
.vita-metric-card > strong {font-size:clamp(32px,3.2vw,43px); line-height:1.15; color:#0C1D7F;}
.vita-targets {display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:22px;}
.vita-target-card {padding:28px; border:1px solid #80D7D9; border-radius:20px; background:#FFFFFF; color:#0C1D7F;}
.vita-target-card > strong {display:block; font-size:clamp(42px,4.5vw,64px); line-height:1.1; margin:18px 0;}
.vita-target-card > h3 {font-size:21px; line-height:1.3; margin:0;}
.vita-target-card--loss {background:#80D7D9; border-color:#80D7D9;}
.vita-channel-actions {display:flex; flex-wrap:wrap; gap:12px; margin-top:14px;}
.vita-channel-actions .v-icon {width:20px; height:20px;}
.vita-app-link-slots {display:flex; flex-wrap:wrap; gap:12px; margin-top:auto; padding-top:12px; width:100%;}
.vita-app-slot {min-height:46px; flex:1; padding:12px 18px; display:flex; align-items:center; justify-content:center; border:1px solid #80D7D9; border-radius:12px; background:#80D7D940; color:#0C1D7F; font-weight:600;}
.vita-territory-section {padding:40px 0 58px; background:#FFFFFF; color:#0C1D7F;}
.vita-territory-grid {display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:22px;}
.vita-territory-card {display:flex; flex-direction:column; border-radius:22px; overflow:hidden; border:1px solid #80D7D980; background:#FFFFFF; color:#0C1D7F; text-decoration:none; transition:transform .2s ease;}
.vita-territory-card > img {width:100%; height:auto; aspect-ratio:16/10; object-fit:cover; transition:transform .35s ease;}
.vita-territory-card > div {display:flex; gap:16px; align-items:center; justify-content:space-between; padding:24px; flex:1;}
.vita-territory-card h3 {font-size:23px; line-height:1.25; margin:0; color:#0C1D7F;}
.vita-territory-card .v-icon {flex-shrink:0; width:24px;}
.vita-territory-card:hover {transform:translateY(-4px);}
.vita-territory-card:hover > img {transform:scale(1.025);}
.vita-home-stats-bar {background:#0C1D7F; color:#FFFFFF; padding:32px 0;}
.vita-home-stats-bar .vita-stats {margin-block:0; border:0; border-radius:0; padding:0; display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:24px;}
.vita-home-stats-bar .vita-stats > div {padding:12px 20px; border-right:1px solid #80D7D955;}
.vita-home-stats-bar .vita-stats > div:last-child {border:0;}
.vita-home-stats-bar dt {font-size:clamp(30px,3vw,43px); font-weight:700; line-height:1.15; margin-bottom:9px;}
.vita-home-stats-bar dd {font-size:16px; line-height:1.45; margin:0;}
.v-home .s-news {padding-block:36px;}
.v-home .v-news-grid {display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:24px;}
.v-home .v-news {display:grid; grid-template-columns:140px minmax(0,1fr); min-height:0; overflow:hidden; border:1px solid #80D7D980; border-radius:18px; background:#FFFFFF;}
.v-home .v-news > img,.v-home .v-news-brand {width:100%; height:100%; min-height:166px; aspect-ratio:auto; object-fit:cover; margin:0;}
.v-home .v-news-brand {display:flex; align-items:center; justify-content:center; background:#80D7D925; padding:16px;}
.v-home .v-news-brand img {width:100%; height:auto;}
.v-home .v-news-copy {padding:21px; display:flex; flex-direction:column; gap:10px;}
.v-home .v-news-copy h3 {font-size:20px; line-height:1.3; margin:0;}
.v-home .v-news-copy time {font-size:13px;}
.v-home .v-news-copy > span {font-size:14px; margin-top:auto;}
/* City names remain accessible on markers but visible only in the sidebar. */
.ma .ma-native-label,.ma [data-map-label] {display:none !important;}
.vita-footer-groups {display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:24px;}
.brand-footer .vita-footer-groups h3 {margin:0 0 12px; color:#FFFFFF; font-size:15px; font-weight:700; line-height:1.3;}
.brand-footer .vita-footer-groups ul {display:flex !important; flex-direction:column; gap:8px; padding:0; margin:0; list-style:none;}
.brand-footer .vita-footer-groups a {font-size:13px; line-height:1.4; text-decoration:none;}
@media(max-width:1100px) {
  .vita-document-grid--four {grid-template-columns:repeat(2,minmax(0,1fr));}
  .vita-document-card,.vita-related-card {padding:23px;}
  .v-home .v-news {grid-template-columns:110px minmax(0,1fr);}
  .v-home .v-news-copy h3 {font-size:18px;}
}
@media(max-width:760px) {
  .vita-document-page .vita-page-hero-grid {grid-template-columns:1fr; gap:25px;}
  .vita-document-page .vita-page-photo {aspect-ratio:16/9; max-height:320px;}
  .vita-document-grid,.vita-targets,.vita-territory-grid {grid-template-columns:repeat(2,minmax(0,1fr)); gap:16px;}
  .vita-document-grid--two {grid-template-columns:repeat(2,minmax(0,1fr));}
  .vita-document-steps {grid-template-columns:1fr;}
  .vita-calculator-wrap .vs-oqf-calculator {grid-template-columns:1fr; padding:24px; gap:22px;}
  .vita-report-card {align-items:flex-start; flex-direction:column;}
  .vita-home-stats-bar .vita-stats {grid-template-columns:repeat(2,minmax(0,1fr)); gap:18px;}
  .vita-home-stats-bar .vita-stats > div {padding:10px; border:0;}
  .v-home .v-news-grid {grid-template-columns:1fr; gap:16px;}
  .v-home .v-news {grid-template-columns:130px minmax(0,1fr);}
  .vita-wa-float {width:56px; height:56px; right:16px; bottom:max(16px,env(safe-area-inset-bottom));}
  .vita-wa-float img {width:31px; height:31px;}
}
@media(max-width:520px) {
  .vita-document-grid,.vita-document-grid--four,.vita-document-grid--two,.vita-targets,.vita-territory-grid {grid-template-columns:1fr;}
  .vita-document-nav {padding-block:20px; gap:8px;}
  .vita-document-nav a {font-size:14px; padding:10px 12px;}
  .vita-document-fold > summary {width:calc(100% - 32px); font-size:24px;}
  .vita-document-steps li {padding:20px; gap:13px;}
  .vita-document-section {padding-block:32px;}
  .vita-document-figure {padding:8px; margin-block:20px; border-radius:14px;}
  .vita-process-group > h3 {font-size:16px;}
  .vita-report-card {padding:22px;}
  .vita-calculator-wrap .vs-oqf-calculator {padding:21px;}
  .vita-target-card > strong {font-size:49px;}
  .vita-territory-card > div {padding:21px;}
  .vita-home-stats-bar dt {font-size:30px;}
  .vita-home-stats-bar dd {font-size:14px;}
  .v-home .v-news {grid-template-columns:100px minmax(0,1fr);}
  .v-home .v-news-copy {padding:16px;}
  .v-home .v-news-copy h3 {font-size:17px;}
  .vita-official-contact strong {font-size:13px;}
  .vita-official-contact small {font-size:10px;}
  .brand-utility-inner > nav {gap:9px;}
  .vita-official-contact img {width:21px; height:21px;}
  .brand-utility .brand-service {font-size:12px; padding-inline:12px;}
}
@media(prefers-reduced-motion:reduce) {
  .vita-wa-float::before {animation:none;}
  .vita-wa-float,.vita-territory-card,.vita-territory-card > img,.vita-related-card {transition:none;}
}

.vita-contact-form {max-width:900px; margin-inline:auto; padding:32px; background:#FFFFFF; color:#0C1D7F; border:1px solid #80D7D9; border-radius:24px;}
.vita-contact-form h2 {font-size:clamp(27px,3vw,36px); line-height:1.2; margin:0 0 26px;}
.vita-contact-fields {display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:22px;}
.vita-contact-field {display:flex; flex-direction:column; gap:8px;}
.vita-contact-field label {font-weight:600; color:#0C1D7F;}
.vita-contact-field :is(input,textarea) {display:block; width:100%; max-width:100%; min-height:48px; padding:12px 14px; border:1px solid #0C1D7F50; border-radius:10px; font:inherit; color:#0C1D7F; background:#FFFFFF;}
.vita-contact-field input[type=file] {font-size:14px; padding:12px;}
.vita-contact-field textarea {resize:vertical;}
.vita-contact-field--wide {grid-column:1/-1;}
.vita-contact-consent {display:flex; align-items:flex-start; gap:12px; margin:24px 0; font-size:14px; line-height:1.55;}
.vita-contact-consent input {margin-top:5px; accent-color:#0C1D7F;}
.vita-contact-form .vita-form-submit:disabled {opacity:.6; cursor:default;}
.vita-report-card [aria-disabled=true] {opacity:.65; cursor:default;}
@media(max-width:600px){.vita-contact-form{padding:22px}.vita-contact-fields{grid-template-columns:1fr; gap:18px}}

/* Revisão documental: faixa de números em branco após Quem Somos. */
body.vita-redesign .vita-home-stats-bar {background:#FFFFFF; background-image:none; color:#0C1D7F; border-block:1px solid #80D7D980;}
body.vita-redesign .vita-home-stats-bar .vita-stats {background:transparent; color:#0C1D7F;}
body.vita-redesign .vita-home-stats-bar :is(dt,dd) {color:#0C1D7F;}
body.vita-redesign .vita-home-stats-bar .vita-stats > div {border-right-color:#80D7D9;}
body.vita-redesign .vita-home-stats-bar dt::after {content:""; display:block; width:32px; height:3px; margin-top:10px; border-radius:3px; background:#FEC400;}
